-- =====================================================================
-- Session 434 — Revelation cross-references brought into the settled order of the end
-- (1 Thessalonians 4 two events; Revelation re-map, locked 2026-10-02)
-- =====================================================================
-- Updates the stored notes, thread titles/summaries and member notes written by
-- session181 (Revelation threads), session224 (Revelation full-library) and
-- session233 (1 Thessalonians), which predate the re-map. The source migrations
-- were corrected in place to the same text, so a fresh rebuild matches prod.
-- Adds the missing Revelation 17:8-11 thread (the beast out of the pit).
-- Apply:  python3 api/apply_migration.py data-schema/migrations/session434_revelation_order_of_end_xref_corrections.sql
-- =====================================================================

\echo 'session434 — Revelation order-of-end corrections starting...'
BEGIN;

CREATE TEMP VIEW _s434_lu AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29');

-- ===== corrections to session224 =====

UPDATE cross_references x SET note = E'*But thou, O Daniel, shut up the words, and seal the book, even to the time of the end: many shall run to and fro, and knowledge shall be increased* (Daniel 12:4). Daniel was shown the like: a book shut up and sealed *even to the time of the end,* its words kept from every reader. John stands before a sealed book too, and he *wept much, because no man was found worthy to open and to read the book* (Revelation 5:4). Daniel is a witness that Yahuah (LORD) keeps his counsel sealed until its appointed hour; Revelation itself names who opens this book — *the Lion of the tribe of Juda, the Root of David, hath prevailed to open the book, and to loose the seven seals thereof* (Revelation 5:5).'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=5 AND sv.verse_number=4
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=12 AND tv.verse_number=4
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*A fiery stream issued and came forth from before him: thousand thousands ministered unto him, and ten thousand times ten thousand stood before him: the judgment was set, and the books were opened* (Daniel 7:10). John''s count of the worshippers is Daniel''s exact number: *the number of them was ten thousand times ten thousand, and thousands of thousands* (Revelation 5:11). Daniel saw the like before the Ancient of days, a heavenly court beyond counting; he stands as a witness, and John beholds such a host round about the throne, gathered now to cry *Worthy is the Lamb that was slain* (Revelation 5:12).'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=5 AND sv.verse_number=11
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=10
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And say unto them, Thus saith Adonai Yahuah (the Lord GOD); Behold, I will take the children of Yashar''el (Israel) from among the heathen, whither they be gone, and will gather them on every side, and bring them into their own land:* (Ezekiel 37:21). The sealing comes first, and the gathering follows. *There were sealed an hundred and forty and four thousand of all the tribes of the children of Yashar''el (Israel)* (Revelation 7:4) — marked for keeping before the winds are loosed and the sifting begins, so that the ones Yahuah (LORD) will *take... from among the heathen... and gather... on every side* are counted and kept beforehand. The numbering of the tribes in Revelation 7 is the roll of those sealed for the gathering, every house accounted for before the homecoming.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=7 AND sv.verse_number=4
   AND tv.edition_slug='canon' AND tv.book_slug='ezekiel' AND tv.chapter_number=37 AND tv.verse_number=21
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*Arise up and stand, behold the number of those that be sealed in the feast of Yahuah (God);* (2 Esdras 2:38). *And I heard the number of them which were sealed* (Revelation 7:4). The restored library knows this sealed and numbered company: a counted people, sealed and gathered to the feast of Yahuah (God). The 144,000 of all the tribes of Yashar''el (Israel) is the number Esdras is bidden to behold — every tribe sealed and reckoned beforehand, kept for the day the houses are brought in to keep the feast.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=7 AND sv.verse_number=4
   AND tv.edition_slug='apocrypha' AND tv.book_slug='2-esdras' AND tv.chapter_number=2 AND tv.verse_number=38
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And ye shall take you on the first day the boughs of goodly trees, branches of palm trees, and the boughs of thick trees, and willows of the brook; and ye shall rejoice before Yahuah Elohaychem (the LORD your God) seven days.* (Leviticus 23:40). The palms in the multitude''s hands are the palms of the feast of ingathering: *clothed with white robes, and palms in their hands* (Revelation 7:9). At Sukkot Yashar''el (Israel) took *branches of palm trees* and rejoiced before Yahuah Elohaychem (the LORD your God) — the feast that remembers the wilderness journey and the gathering-in of the harvest. The gathered multitude keeps the great Sukkot, palms in hand, rejoicing before the throne as the scattered seed is brought home from the nations.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=7 AND sv.verse_number=9
   AND tv.edition_slug='canon' AND tv.book_slug='leviticus' AND tv.chapter_number=23 AND tv.verse_number=40
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*How art thou fallen from heaven, O Lucifer, son of the morning! how art thou cut down to the ground, which didst weaken the nations!* (Isaiah 14:12). *I saw a star fall from heaven unto the earth: and to him was given the key of the bottomless pit* (Revelation 9:1). Isaiah''s taunt is the proverb taken up *against the king of Babylon* (Isaiah 14:4) — Babel''s proud king *cut down to the ground.* The seer watches a star come down to the earth and be *given* the key; the pit it unlocks is the very place to which Babel''s king was brought down. Isaiah stands as witness to whose chamber this is, not as the name of the star that opens it.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=9 AND sv.verse_number=1
   AND tv.edition_slug='canon' AND tv.book_slug='isaiah' AND tv.chapter_number=14 AND tv.verse_number=12
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*For thou hast said in thine heart, I will ascend into heaven, I will exalt my throne above the stars of Elohim (God): I will sit also upon the mount of the congregation, in the sides of the north* (Isaiah 14:13). This is the boast of Babel''s king, the pride that reached for heaven and said in his heart *I will exalt my throne above the stars of Elohim (God).* Isaiah shows where that boast ends: in the pit. And at the fifth trumpet *I saw a star fall from heaven unto the earth: and to him was given the key of the bottomless pit* (Revelation 9:1) — the key to the very chamber where the would-be ascender was laid, out of which the king of the locusts now rises.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=9 AND sv.verse_number=1
   AND tv.edition_slug='canon' AND tv.book_slug='isaiah' AND tv.chapter_number=14 AND tv.verse_number=13
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*Yet thou shalt be brought down to hell, to the sides of the pit.* (Isaiah 14:15). The end of the one who said *I will ascend* is the pit: *brought down to hell, to the sides of the pit.* And here the seer sees that very pit unlocked — *to him was given the key of the bottomless pit* (Revelation 9:1). The chamber Isaiah named as the destiny of Babel''s proud king is the chamber out of which the smoke and the locusts now rise; the pit is real, and its mouth is opened.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=9 AND sv.verse_number=1
   AND tv.edition_slug='canon' AND tv.book_slug='isaiah' AND tv.chapter_number=14 AND tv.verse_number=15
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And I saw one of those four who had come forth first, and he seized that first star which had fallen from the heaven, and bound it hand and foot and cast it into an abyss: now that abyss was narrow and deep, and horrible and dark.* (1 Enoch 88:1). Here the Hebrew library shows the fallen star itself — *that first star which had fallen from the heaven* — seized, bound, and *cast into an abyss... narrow and deep, and horrible and dark.* John sees a star at the mouth of the same chamber: *I saw a star fall from heaven unto the earth: and to him was given the key of the bottomless pit* (Revelation 9:1). The star, the fall, the abyss are one across the witnesses.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=9 AND sv.verse_number=1
   AND tv.edition_slug='enoch' AND tv.book_slug='1-enoch' AND tv.chapter_number=88 AND tv.verse_number=1
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And again Yahuah (God) said to Raphael: ''Bind Azâzêl hand and foot, and cast him into the darkness: and make an opening in the desert, which is in Dûdâêl, and cast him therein.* (1 Enoch 10:4). The Hebrew library knows the pit as a prison. Azazel is *bound hand and foot* and cast into the darkness of a chasm in the desert — a witness that the deep holds its bound ones until the appointed hour. But the king of the locusts is not the one cast down from heaven. *A king over them, which is the angel of the bottomless pit* (Revelation 9:11), whose name is Destruction, is Babel''s king, Nimrod — the one the dragon raises up, ruling from the underworld, the beast out of the pit that *was, and is not; and shall ascend out of the bottomless pit, and go into perdition* (Revelation 17:8).'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=9 AND sv.verse_number=11
   AND tv.edition_slug='enoch' AND tv.book_slug='1-enoch' AND tv.chapter_number=10 AND tv.verse_number=4
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*His body also was like the beryl, and his face as the appearance of lightning, and his eyes as lamps of fire, and his arms and his feet like in colour to polished brass, and the voice of his words like the voice of a multitude.* (Daniel 10:6). The mighty angel''s *face was as it were the sun, and his feet as pillars of fire* (Revelation 10:1). Daniel saw the like by the great river: a man clothed in linen, face blazing, feet as burnished brass, voice as a multitude, sent *to make thee understand what shall befall thy people in the latter days* (Daniel 10:14). Daniel stands here as a witness that Elohim (God) clothes his messengers in fire and light; Revelation tells of its own mighty angel, the one John sees *come down from heaven, clothed with a cloud* (Revelation 10:1).'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=10 AND sv.verse_number=1
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=10 AND tv.verse_number=6
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And I heard the man clothed in linen, which was upon the waters of the river, when he held up his right hand and his left hand unto heaven, and sware by him that liveth for ever that it shall be for a time, times, and an half; and when he shall have accomplished to scatter the power of the holy people, all these things shall be finished.* (Daniel 12:7). *And the angel which I saw stand upon the sea and upon the earth lifted up his hand to heaven, and sware by him that liveth for ever and ever* (Revelation 10:5-6). Daniel was shown the like: the man clothed in linen upon the waters, the hand lifted, the oath *by him that liveth for ever,* the declaration that *all these things shall be finished.* Daniel stands as a witness to such an oath, and Daniel''s measure stays in Daniel. John''s angel swears by the same Living One, and Revelation speaks its own finishing: *the mystery of Elohim (God) should be finished* (Revelation 10:7).'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=10 AND sv.verse_number=5
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=12 AND tv.verse_number=7
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*The people of thy holiness have possessed it but a little while: our adversaries have trodden down thy sanctuary.* (Isaiah 63:18). Isaiah''s lament is the same grief — *our adversaries have trodden down thy sanctuary.* *The holy city shall they tread under foot forty and two months* (Revelation 11:2). But the treading is *a little while*; the adversaries hold the outer court only for the appointed season, and the prayer of Isaiah for the *tribes of thine inheritance* is the cry the measured temple answers — the sanctuary trodden for the nations'' forty and two months and no longer, the treading ended before the reign begins.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=11 AND sv.verse_number=2
   AND tv.edition_slug='canon' AND tv.book_slug='isaiah' AND tv.chapter_number=63 AND tv.verse_number=18
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*Then answered I, and said unto him, What are these two olive trees upon the right side of the candlestick and upon the left side thereof?* (Zechariah 4:11). The prophet''s own question — *What are these two olive trees?* — is answered in the seer''s declaration: *These are the two olive trees, and the two candlesticks* (Revelation 11:4). Zechariah asked and Revelation tells: the two olive trees are the two witnesses, the two houses, Yahudah (Judah) and Yashar''el (Israel), the anointed who stand before Yahuah (LORD) and carry his light through the thousand two hundred and threescore days of their prophecy in the reign.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=11 AND sv.verse_number=4
   AND tv.edition_slug='canon' AND tv.book_slug='zechariah' AND tv.chapter_number=4 AND tv.verse_number=11
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And Elijah the Tishbite, who was of the inhabitants of Gilead, said unto Ahab, As Yahuah Elohim (the LORD God) of Yashar''el (Israel) liveth, before whom I stand, there shall not be dew nor rain these years, but according to my word.* (1 Kings 17:1). Elijah shut up the heaven by his word — *there shall not be dew nor rain these years, but according to my word.* So the witnesses *have power to shut heaven, that it rain not in the days of their prophecy* (Revelation 11:6). The witnesses carry Elijah''s very gift: the two houses, Yahudah (Judah) and Yashar''el (Israel), walking in the pattern of the Tishbite who stood before Yahuah (LORD) and held back the rain.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=11 AND sv.verse_number=6
   AND tv.edition_slug='canon' AND tv.book_slug='1-kings' AND tv.chapter_number=17 AND tv.verse_number=1
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*Thus saith Yahuah (LORD), In this thou shalt know that I am Yahuah (LORD): behold, I will smite with the rod that is in mine hand upon the waters which are in the river, and they shall be turned to blood.* (Exodus 7:17). Moses turned the river to blood — *I will smite with the rod... and they shall be turned to blood.* So the witnesses *have power over waters to turn them to blood, and to smite the earth with all plagues, as often as they will* (Revelation 11:6). The witnesses carry the pattern of Moses, who smote Egypt with plagues. Moses and Elijah are the pattern of their gifts, not the witnesses themselves; the two witnesses of Yahuah (LORD) are the two houses, Yahudah (Judah) and Yashar''el (Israel), testifying in the power of the law and the prophets.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=11 AND sv.verse_number=6
   AND tv.edition_slug='canon' AND tv.book_slug='exodus' AND tv.chapter_number=7 AND tv.verse_number=17
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*Then stood up Elias the prophet as fire, and his word burned like a lamp.* (Sirach 48:1). The Hebrew library remembered Elijah as fire itself — *Elias the prophet as fire, and his word burned like a lamp.* So of the witnesses: *fire proceedeth out of their mouth, and devoureth their enemies* (Revelation 11:5). The witnesses whose mouth burns walk in the pattern of the prophet whose very word *burned like a lamp* — and the two candlesticks of verse 4 are these burning lamps, the prophetic word of Yahuah (LORD) made fire.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=11 AND sv.verse_number=5
   AND tv.edition_slug='apocrypha' AND tv.book_slug='ecclesiasticus' AND tv.chapter_number=48 AND tv.verse_number=1
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*By the word of Yahuah (God) he shut up the heaven, and also three times brought down fire.* (Sirach 48:3). The library names both gifts the witnesses carry, and joins them in Elijah: *By the word of Yahuah (God) he shut up the heaven, and also three times brought down fire.* So the witnesses *have power to shut heaven, that it rain not* (Revelation 11:6) and *fire proceedeth out of their mouth* (Revelation 11:5). The shut heaven and the called-down fire are Elijah''s twin signs, and the two witnesses of the chapter, the two houses, Yahudah (Judah) and Yashar''el (Israel), walk in the pattern of Elijah and of Moses both.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=11 AND sv.verse_number=6
   AND tv.edition_slug='apocrypha' AND tv.book_slug='ecclesiasticus' AND tv.chapter_number=48 AND tv.verse_number=3
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*I beheld, and the same horn made war with the saints, and prevailed against them* (Daniel 7:21). Daniel was shown the like — a horn making war on the holy ones and overcoming them for a season — *the same horn made war with the saints, and prevailed against them.* So, in the little season after the reign, the beast out of the pit (not the beast out of the sea, already in the lake) makes its war: *the beast that ascendeth out of the bottomless pit shall make war against them, and shall overcome them, and kill them* (Revelation 11:7). Daniel stands here as a witness to the pattern, not the key to the figure: war on the saints always ends in the verdict — *until the Ancient of days came, and judgment was given to the saints* (Daniel 7:22) — and so here the slain witnesses rise at the last trump (Revelation 11:11); the killing is not the end of the story.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=11 AND sv.verse_number=7
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=21
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*So I prophesied as he commanded me, and the breath came into them, and they lived, and stood up upon their feet, an exceeding great army.* (Ezekiel 37:10). The words are nearly the same: *the breath came into them, and they lived, and stood up upon their feet.* So of the witnesses: *the Spirit of life from Elohim (God) entered into them, and they stood upon their feet* (Revelation 11:11). And Ezekiel told what the raising meant — *these bones are the whole house of Yashar''el (Israel)* (Ezekiel 37:11), the graves opened and the people brought home; the standing witnesses are the righteous rising at the great resurrection, the graves of the whole house opened at the last.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=11 AND sv.verse_number=11
   AND tv.edition_slug='canon' AND tv.book_slug='ezekiel' AND tv.chapter_number=37 AND tv.verse_number=10
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And it came to pass, as they still went on, and talked, that, behold, there appeared a chariot of fire, and horses of fire, and parted them both asunder; and Elijah went up by a whirlwind into heaven.* (2 Kings 2:11). Elijah was taken up — *Elijah went up by a whirlwind into heaven.* So the witnesses: *they heard a great voice from heaven saying unto them, Come up hither. And they ascended up to heaven in a cloud* (Revelation 11:12). Elijah''s ascent is the pattern, not the person: the witnesses are the two houses, Yahudah (Judah) and Yashar''el (Israel), and their going up at *Come up hither* is the catching-up Paul named — *Then we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord* (1 Thessalonians 4:17) — after the reign and the little season.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=11 AND sv.verse_number=12
   AND tv.edition_slug='canon' AND tv.book_slug='2-kings' AND tv.chapter_number=2 AND tv.verse_number=11
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*Who were ordained for reproofs in their times, to pacify the wrath of the judgment of Yahuah (God), before it brake forth into fury, and to turn the heart of the father to the son, and to restore the tribes of Jacob.* (Sirach 48:10). The library names the office Elijah was ordained to, the pattern the witnesses walk in: *ordained for reproofs in their times... to restore the tribes of Jacob.* So the witnesses prophesy and are raised — *the Spirit of life from Elohim (God) entered into them, and they stood upon their feet* (Revelation 11:11). Their testimony, like Elijah''s, is for the reproof and the regathering — the turning of hearts and the restoration of the scattered tribes that the whole vision moves toward.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=11 AND sv.verse_number=11
   AND tv.edition_slug='apocrypha' AND tv.book_slug='ecclesiasticus' AND tv.chapter_number=48 AND tv.verse_number=10
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And Yahuah (LORD) shall be king over all the earth: in that day shall there be one Yahuah (LORD), and his name one.* (Zechariah 14:9). Zechariah''s day of Yahuah (LORD) ends in his universal reign — *Yahuah (LORD) shall be king over all the earth.* So the seventh trumpet: *The kingdoms of this world are become the kingdoms of our Lord, and of his Messiah (Christ); and he shall reign for ever and ever* (Revelation 11:15). The one kingship of Yahuah (LORD) over all the earth that Zechariah saw open the reign is the kingdom the last trump declares complete — *he shall reign for ever and ever* — the whole earth gathered under the one name.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=11 AND sv.verse_number=15
   AND tv.edition_slug='canon' AND tv.book_slug='zechariah' AND tv.chapter_number=14 AND tv.verse_number=9
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And he dreamed yet another dream, and told it his brethren, and said, Behold, I have dreamed a dream more; and, behold, the sun and the moon and the eleven stars made obeisance to me.* (Genesis 37:9). The woman of the vision wears the very signs of Joseph''s dream — *a woman clothed with the sun, and the moon under her feet, and upon her head a crown of twelve stars* (Revelation 12:1). The sun, the moon, the stars: these are Jacob and Rachel and the twelve sons, the covenant family the dream first sketched, and the dream is Joseph''s, head of the northern house. The woman is Yashar''el (Israel), the northern company, no new thing and no replacement; she is the people of the promise, clothed in the lights of heaven, carrying the seed.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=12 AND sv.verse_number=1
   AND tv.edition_slug='canon' AND tv.book_slug='genesis' AND tv.chapter_number=37 AND tv.verse_number=9
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*Sing, O barren, thou that didst not bear; break forth into singing, and cry aloud, thou that didst not travail with child: for more are the children of the desolate than the children of the married wife, saith Yahuah (LORD).* (Isaiah 54:1). The woman *being with child cried, travailing in birth, and pained to be delivered* (Revelation 12:2). Isaiah set the figure long before: Zion as the travailing woman whose desolation turns to a multitude of children. The pangs are real and the deliverance is sure — Isaiah''s Zion a witness to the pattern, and the woman of the vision, Yashar''el (Israel), the northern company, bringing forth the seed of promise out of her affliction.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=12 AND sv.verse_number=2
   AND tv.edition_slug='canon' AND tv.book_slug='isaiah' AND tv.chapter_number=54 AND tv.verse_number=1
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*Be in pain, and labour to bring forth, O daughter of Zion, like a woman in travail: for now shalt thou go forth out of the city, and thou shalt dwell in the field, and thou shalt go even to Babylon; there shalt thou be delivered; there Yahuah (LORD) shall redeem thee from the hand of thine enemies.* (Micah 4:10). The travail of the woman *pained to be delivered* (Revelation 12:2) is the travail Micah was shown the like of — the daughter of Zion labouring through exile and dwelling in the field, a witness to the pattern the northern company, Yashar''el (Israel), now walks, yet promised deliverance and redemption from her enemies'' hand. Her labour ends not in loss but in the redeeming of the seed.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=12 AND sv.verse_number=2
   AND tv.edition_slug='canon' AND tv.book_slug='micah' AND tv.chapter_number=4 AND tv.verse_number=10
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And at that time shall Michael stand up, the great prince which standeth for the children of thy people: and there shall be a time of trouble, such as never was since there was a nation even to that same time: and at that time thy people shall be delivered, every one that shall be found written in the book.* (Daniel 12:1). The rising of *Michael and his angels* (Revelation 12:7) is the standing-up Daniel foretold — *Michael... the great prince which standeth for the children of thy people* — and it brings the deliverance of all *found written in the book.* Daniel was shown the like: Michael stands, and the people found in the book are delivered. Here the dragon is cast down, but his war is not finished — *the dragon was wroth with the woman, and went to make war with the remnant of her seed* (Revelation 12:17), until the reign; the deliverance comes at the end of that war.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=12 AND sv.verse_number=7
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=12 AND tv.verse_number=1
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And four great beasts came up from the sea, diverse one from another.* (Daniel 7:3). The seer stands on the sand and sees *a beast rise up out of the sea, having seven heads and ten horns* (Revelation 13:1) — and Daniel''s four beasts come up *from the sea* before him. The waters are the seething nations, and out of them the kingdoms rise; Daniel was shown four, and John sees one beast out of the sea bearing features of them all. Daniel stands as a witness to the kind of thing John sees; he does not decide what John''s beast out of the sea is.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=13 AND sv.verse_number=1
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=3
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*After this I saw in the night visions, and behold a fourth beast, dreadful and terrible, and strong exceedingly; and it had great iron teeth: it devoured and brake in pieces, and stamped the residue with the feet of it: and it was diverse from all the beasts that were before it; and it had ten horns.* (Daniel 7:7). Daniel''s dreadful fourth beast *had ten horns*; John''s beast has *ten horns, and upon his horns ten crowns* (Revelation 13:1). The ten horns are a likeness the two visions share: Daniel was shown a ten-horned terror, and John''s beast out of the sea bears ten horns too, a witness to the kind, not a decree that John''s beast is Daniel''s fourth kingdom.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=13 AND sv.verse_number=1
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=7
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*Thus he said, The fourth beast shall be the fourth kingdom upon earth, which shall be diverse from all kingdoms, and shall devour the whole earth, and shall tread it down, and break it in pieces.* (Daniel 7:23). The angel told Daniel the fourth beast is *the fourth kingdom upon earth* that shall *devour the whole earth*; John sees the like reach given his beast out of the sea — *power was given him over all kindreds, and tongues, and nations* (Revelation 13:7), the world-wide dominion of the one beast rising *out of the sea* (Revelation 13:1) with *seven heads and ten horns*.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=13 AND sv.verse_number=1
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=23
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*The eagle, whom you sawest come up from the sea, is the kingdom which was seen in the vision of your brother Daniel.* (2 Esdras 12:11). The interpreting voice tells Ezra that his sea-eagle answers to the kingdom of Daniel''s vision; that is Ezra''s key to Ezra''s own eagle. John''s beast out of the sea rises *having seven heads and ten horns* (Revelation 13:1), and the library stands beside it as witness: kingdoms rising from the sea of the nations, given dominion until El Elyon (the most High) judges them. Revelation''s figure is read in Revelation; Daniel and Ezra witness to the kind, they do not decide what John''s beast is.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=13 AND sv.verse_number=1
   AND tv.edition_slug='apocrypha' AND tv.book_slug='2-esdras' AND tv.chapter_number=12 AND tv.verse_number=11
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And he shall speak great words against the El Elyon (most High), and shall wear out the saints of the El Elyon (most High), and think to change times and laws: and they shall be given into his hand until a time and times and the dividing of time.* (Daniel 7:25). Revelation gives the season of the beast out of the sea in its own unit: *power was given unto him to continue forty and two months* (Revelation 13:5) — forty and two months, kept as Revelation counts it and not traded for Daniel''s measure. And Daniel''s horn witnesses to its character: it *speak[s] great words against the El Elyon (most High)* and *think[s] to change times and laws.* The beast-system makes war on the commandments of Yahuah (LORD), reaching to alter the very times and laws he appointed; that is the blasphemy John names, and the saints are *given into his hand* for the appointed season — but only the season.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=13 AND sv.verse_number=5
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=25
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*I beheld, and the same horn made war with the saints, and prevailed against them* (Daniel 7:21). *It was given unto him to make war with the saints, and to overcome them* (Revelation 13:7) — the beast out of the sea makes the war Daniel was shown the like of, and for a season wins. But Daniel saw the end of it too: *until the Ancient of days came, and judgment was given to the saints of the El Elyon (most High); and the time came that the saints possessed the kingdom* (Daniel 7:22). The overcoming is real and it is bounded; the patience of the saints holds because the verdict has already been given in their favour.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=13 AND sv.verse_number=7
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=21
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And the king shall do according to his will; and he shall exalt himself, and magnify himself above every god, and shall speak marvellous things against the Elohim (God) of gods, and shall prosper till the indignation be accomplished: for that that is determined shall be done.* (Daniel 11:36). The self-exalting king who *speak[s] marvellous things against the Elohim (God) of gods* is of one spirit with the beast that *opened his mouth in blasphemy against Elohim (God), to blaspheme his name, and his tabernacle* (Revelation 13:6). And a limit is set on each in its own measure: Daniel''s king prospers only *till the indignation be accomplished*; the beast out of the sea only for the *forty and two months* (Revelation 13:5). The mouth is loud, but the clock is the Father''s.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=13 AND sv.verse_number=6
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=11 AND tv.verse_number=36
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* (Daniel 7:13). The seer looks and *behold a white cloud, and upon the cloud one sat like unto the Son of Adam, having on his head a golden crown* (Revelation 14:14). Daniel was shown the like — *one like the Son of Adam came with the clouds of heaven* — and his vision stands as a witness to the same cloud-rider. The kaph is preserved in both: *one LIKE the Son of Adam,* not a bare title but the One who resembles a son of mortal-man because he took on flesh, while remaining the Formed cloud-rider who comes to the Ancient of days. The golden crown is upon him, the kingdom Daniel saw given; the cloud-rider of Daniel 7 sits enthroned for the harvest.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=14 AND sv.verse_number=14
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=13
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And when the ears shall be cut down, which are without number, how great a floor shall they fill?* (2 Esdras 4:32). When *the earth was reaped* (Revelation 14:16), the ears beyond number are cut down and the great floor is filled — the very figure the restored library uses for the time of threshing, *the ears... cut down... how great a floor shall they fill.* The ears cut down are the grain of evil seed the verse before named (2 Esdras 4:30) — the tares, bound and brought to the floor first. The reaping of the earth is that filling of the floor: the wicked cut down when the Day of Yahuah (LORD) breaks, before ever the wheat is gathered.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=14 AND sv.verse_number=16
   AND tv.edition_slug='apocrypha' AND tv.book_slug='2-esdras' AND tv.chapter_number=4 AND tv.verse_number=32
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And it shall become small dust in all the land of Egypt, and shall be a boil breaking forth with blains upon man, and upon beast, throughout all the land of Egypt.* (Exodus 9:9). The first vial re-speaks the sixth plague of Egypt: *there fell a noisome and grievous sore upon the men which had the mark of the beast, and upon them which worshipped his image* (Revelation 16:2). The same Yahuah (LORD) who smote Pharaoh''s land with the boil now smites the kingdom of the beast — and he smites by the very mark: the sore falls on those who took the mark of the beast out of the sea in their thought and in their deed, the forehead and the hand where Yahuah (LORD) sets his own sign. The new exodus judges the new Egypt by the old sign.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=16 AND sv.verse_number=2
   AND tv.edition_slug='canon' AND tv.book_slug='exodus' AND tv.chapter_number=9 AND tv.verse_number=9
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And there shall be an highway for the remnant of his people, which shall be left, from Assyria; like as it was to Yashar''el (Israel) in the day that he came up out of the land of Egypt.* (Isaiah 11:16). The river dried makes *an highway for the remnant of his people... like as it was... in the day that he came up out of the land of Egypt.* So the Euphrates *dried up, that the way of the kings of the east might be prepared* (Revelation 16:12): the kings of the east are the gathered seed themselves, the remnant coming home from the lands of the scattering beyond the river, and the highway is theirs. The restored library saw the same crossing, when *the Highest shall stay the springs of the stream again, that they may go through* (2 Esdras 13:47) — the second exodus through the dried river, judgment on Babylon and the gathering home in one act.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=16 AND sv.verse_number=12
   AND tv.edition_slug='canon' AND tv.book_slug='isaiah' AND tv.chapter_number=11 AND tv.verse_number=16
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*Therefore thus saith Yahuah (LORD); Behold, I will plead thy cause, and take vengeance for thee; and I will dry up her sea, and make her springs dry.* (Jeremiah 51:36). Yahuah (LORD) swore over Babylon, *I will dry up her sea, and make her springs dry.* The vial enacts it on the great river: *the water thereof was dried up, that the way of the kings of the east might be prepared* (Revelation 16:12). The drying of Babylon''s waters that Jeremiah promised is the drying of the Euphrates here — Babylon''s judgment begun, and her river made a road home for the gathered seed, the kings of the east.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=16 AND sv.verse_number=12
   AND tv.edition_slug='canon' AND tv.book_slug='jeremiah' AND tv.chapter_number=51 AND tv.verse_number=36
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*In that day shall there be a great mourning in Jerusalem, as the mourning of Hadadrimmon in the valley of Megiddon.* (Zechariah 12:11). Zechariah names the very ground: *the valley of Megiddon*, har-Megiddon — Armageddon. *And he gathered them together into a place called in the Hebrew tongue Armageddon* (Revelation 16:16). The name carries the memory of Megiddo, the place of Yashar''el''s (Israel''s) great mournings and battles — and Zechariah sets that mourning in Jerusalem, in the day Yahuah (LORD) goes forth against the gathered nations: *For I will gather all nations against Jerusalem to battle* (Zechariah 14:2); *Then shall Yahuah (LORD) go forth, and fight against those nations* (Zechariah 14:3). Armageddon is that battle of Zechariah 14, at the front edge of the Day, when his feet stand upon the mount of Olives.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=16 AND sv.verse_number=16
   AND tv.edition_slug='canon' AND tv.book_slug='zechariah' AND tv.chapter_number=12 AND tv.verse_number=11
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*The kings came and fought, then fought the kings of Canaan in Taanach by the waters of Megiddo; they took no gain of money.* (Judges 5:19). The song of Deborah remembers when *the kings came and fought... by the waters of Megiddo* and Yahuah (LORD) broke them, the very stars fighting against Sisera. So *he gathered them together into a place called in the Hebrew tongue Armageddon* (Revelation 16:16) — the kings of the earth drawn, as to Megiddo of old, to be broken by the hand of Yahuah (LORD) — the battle Zechariah saw, when Yahuah (LORD) shall *go forth, and fight against those nations, as when he fought in the day of battle* (Zechariah 14:3).'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=16 AND sv.verse_number=16
   AND tv.edition_slug='canon' AND tv.book_slug='judges' AND tv.chapter_number=5 AND tv.verse_number=19
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*In his days Pharaoh-nechoh king of Egypt went up against the king of Assyria to the river Euphrates: and king Josiah went against him; and he slew him at Megiddo, when he had seen him.* (2 Kings 23:29). Megiddo is the field where good Josiah fell, slain by Pharaoh''s hand — a place soaked in the memory of kings cut down. To this place the spirits gather the kings of the earth: *a place called in the Hebrew tongue Armageddon* (Revelation 16:16). The name of Megiddo, a name of slaughter and lament, is set on the battle at the front edge of the Day — the battle of Zechariah 14, when Yahuah (LORD) gathers *all nations against Jerusalem to battle* (Zechariah 14:2) and goes forth to fight against them.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=16 AND sv.verse_number=16
   AND tv.edition_slug='canon' AND tv.book_slug='2-kings' AND tv.chapter_number=23 AND tv.verse_number=29
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*After this I saw in the night visions, and behold a fourth beast, dreadful and terrible, and strong exceedingly; and it had great iron teeth: it devoured and brake in pieces, and stamped the residue with the feet of it: and it was diverse from all the beasts that were before it; and it had ten horns.* (Daniel 7:7). The beast the woman sits upon — *full of names of blasphemy, having seven heads and ten horns* (Revelation 17:3) — is named by the angel himself: it is the beast that *shall ascend out of the bottomless pit* (Revelation 17:8), the beast out of the pit, not the beast out of the sea. Daniel was shown the like, a devouring power that *had ten horns,* and his vision stands as a witness to the kind of power horns signify; it is Revelation''s own angel who tells what this beast is.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=17 AND sv.verse_number=3
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=7
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And four great beasts came up from the sea, diverse one from another.* (Daniel 7:3). Daniel''s beasts *came up from the sea,* as the beast out of the sea rose in Revelation 13:1; but the beast that carries the woman is another — it *shall ascend out of the bottomless pit* (Revelation 17:8). The two are not to be run together. The waters where the whore sits are *peoples, and multitudes, and nations* (17:15), and the woman *sit upon a scarlet coloured beast* (Revelation 17:3) — the harlot riding the beast out of the pit, Daniel''s sea-born beasts standing only as a witness that the visions picture kingdoms as beasts.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=17 AND sv.verse_number=3
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=3
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And the ten horns out of this kingdom are ten kings that shall arise: and another shall rise after them; and he shall be diverse from the first, and he shall subdue three kings.* (Daniel 7:24). The angel interprets: *the ten horns which thou sawest are ten kings, which have received no kingdom as yet; but receive power as kings one hour with the beast* (Revelation 17:12). Daniel was shown the like — horns that were *ten kings that shall arise* — and his vision stands as a witness. But it is Revelation''s own angel who interprets these horns: kings given one hour of power, who lend their strength to the beast that ascends out of the pit (Revelation 17:8).'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=17 AND sv.verse_number=12
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=24
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And I will betroth thee unto me for ever; yea, I will betroth thee unto me in righteousness, and in judgment, and in lovingkindness, and in mercies.* (Hosea 2:19). The wife made ready for the Lamb is the wife of Hosea''s betrothal — the one who had played the harlot, brought into the wilderness, and wooed back: *I will betroth thee unto me for ever* (Hosea 2:19), *I will even betroth thee unto me in faithfulness: and thou shalt know Yahuah (LORD)* (Hosea 2:20). *The marriage of the Lamb is come, and his wife hath made herself ready* (Revelation 19:7); and the betrothal *in righteousness* is answered by the Bride *arrayed in fine linen... the righteousness of saints* (Revelation 19:8). The harlot-city is judged; the divorced house is drawn out into the wilderness and betrothed again there — *Therefore, behold, I will allure her, and bring her into the wilderness, and speak comfortably unto her* (Hosea 2:14). *I will say to them which were not my people, Thou art my people* (Hosea 2:23) — the betrothal is spoken on the road home, in the wilderness of the second exodus.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=19 AND sv.verse_number=7
   AND tv.edition_slug='canon' AND tv.book_slug='hosea' AND tv.chapter_number=2 AND tv.verse_number=19
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And, thou son of Adam, thus saith Adonai Yahuah (the Lord GOD); Speak unto every feathered fowl, and to every beast of the field, Assemble yourselves, and come; gather yourselves on every side to my sacrifice that I do sacrifice for you, even a great sacrifice upon the mountains of Yashar''el (Israel), that ye may eat flesh, and drink blood.* (Ezekiel 39:17). The angel standing in the sun cries *to all the fowls that fly in the midst of heaven, Come and gather yourselves together unto the supper of the great Elohim (God)* (Revelation 19:17). It is Ezekiel''s summons word for word — the fowls and the beasts called to *my sacrifice*, the great sacrifice on the mountains of Yashar''el (Israel) when Gog is fallen. The supper of the great Elohim (God) is that sacrifice come, the gathered armies of the beast out of the sea become the feast.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=19 AND sv.verse_number=17
   AND tv.edition_slug='canon' AND tv.book_slug='ezekiel' AND tv.chapter_number=39 AND tv.verse_number=17
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*I beheld then because of the voice of the great words which the horn spake: I beheld even till the beast was slain, and his body destroyed, and given to the burning flame.* (Daniel 7:11). *And the beast was taken... These both were cast alive into a lake of fire burning with brimstone* (Revelation 19:20). Daniel saw the like in his own night vision — a beast whose horn spake *great words*, *slain, and his body destroyed, and given to the burning flame*. Daniel stands here as a witness, not as the key: in Revelation it is the beast out of the sea (Revelation 13:1) and the beast out of the earth, the false prophet (Revelation 13:11), that are taken and cast alive into the lake of fire — and they are cast in here, before the reign. The proud mouth and the lying wonders are silenced in the fire before the thousand years begin.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=19 AND sv.verse_number=20
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=11
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*I beheld till the thrones were cast down, and the Ancient of days did sit, whose garment was white as snow, and the hair of his head like the pure wool: his throne was like the fiery flame, and his wheels as burning fire.* (Daniel 7:9). When John writes *And I saw thrones, and they sat upon them, and judgment was given unto them* (Revelation 20:4), Daniel stands beside him as a witness — Daniel too saw thrones set and the Ancient of days take his seat. But Revelation tells its own scene: these are the thrones of the reign, judgment given to those who live and reign with Messiah (Christ) a thousand years, not the judgment of the dead that comes at the great white throne when the thousand years are finished (Revelation 20:11-12).'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=20 AND sv.verse_number=4
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=9
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*Until the Ancient of days came, and judgment was given to the saints of the El Elyon (most High); and the time came that the saints possessed the kingdom.* (Daniel 7:22). Daniel was shown that the judgment would be *given to the saints* and that they would *possess the kingdom* — and so it is: *judgment was given unto them... and they lived and reigned with Messiah (Christ) a thousand years* (Revelation 20:4). The ones who refused the mark of the beast out of the sea are the ones who now sit on the thrones. Daniel stands here as a witness, not the key: as Daniel was shown the saints given the kingdom, so John sees the saints reign with Messiah (Christ) the thousand years — Revelation''s own measure of the appointed reign.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=20 AND sv.verse_number=4
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=22
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And the earth shall restore those that are asleep in her, and so shall the dust those that dwell in silence, and the secret places shall deliver those souls that were committed to them.* (2 Esdras 7:32). The Hebrew library names the great restoring of the dead — *the earth shall restore those that are asleep in her... the secret places shall deliver those souls* — and its very next word is the seat of judgment. That is the great resurrection, when the dead, small and great, stand before the throne (Revelation 20:12-13). So the seer marks the order: *the rest of the dead lived not again until the thousand years were finished. This is the first resurrection* (Revelation 20:5). The first resurrection is the early exception — the righteous seed brought up out of Sheol to reign; the earth giving back all her sleepers for judgment waits until the thousand years are finished.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=20 AND sv.verse_number=5
   AND tv.edition_slug='apocrypha' AND tv.book_slug='2-esdras' AND tv.chapter_number=7 AND tv.verse_number=32
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*A fiery stream issued and came forth from before him: thousand thousands ministered unto him, and ten thousand times ten thousand stood before him: the judgment was set, and the books were opened.* (Daniel 7:10). Daniel saw the court of heaven seated and *the judgment was set, and the books were opened.* The seer sees the same: *the dead, small and great, stand before Elohim (God); and the books were opened* (Revelation 20:12). Daniel''s opened books stand as a witness to the opened books of the great white throne — the record brought out and the dead judged from what is written. Revelation shows its own scene: the one reckoning of the dead it already sounded at the seventh trumpet, *the time of the dead, that they should be judged* (Revelation 11:18).'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=20 AND sv.verse_number=12
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=10
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*And the Gentiles shall come to thy light, and kings to the brightness of thy rising.* (Isaiah 60:3). John sees Isaiah''s word fulfilled: *the nations of them which are saved shall walk in the light of it: and the kings of the earth do bring their glory and honour into it* (Revelation 21:24). Isaiah saw the nations and their kings drawn to Zion''s light; in the new Jerusalem they walk in the light of the glory of Elohim (God). These nations are the tribes themselves, the company of nations promised to Jacob: *a nation and a company of nations shall be of thee, and kings shall come out of thy loins* (Genesis 35:11). The scattered seed, gathered out of every land, walk in the light of the city and bring their glory and honour into it.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=21 AND sv.verse_number=24
   AND tv.edition_slug='canon' AND tv.book_slug='isaiah' AND tv.chapter_number=60 AND tv.verse_number=3
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_references x SET note = E'*Saying, Hurt not the earth, neither the sea, nor the trees, till we have sealed the servants of our Elohim (God) in their foreheads.* (Revelation 7:3). The servants were sealed *in their foreheads* before the winds were loosed — the mark of the living Elohim (God) set upon the gathered. That seal is now seen for what it is: *his name shall be in their foreheads* (Revelation 22:4). The seal of the seventh chapter is the name of the seventh: the seal set on the servants before the winds of the Day were loosed, before the sifting, is the name they wear before the throne, the counter-sign to the mark of the beast, the name of the One they see face to face.'
  FROM _s434_lu sv, _s434_lu tv
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=22 AND sv.verse_number=4
   AND tv.edition_slug='canon' AND tv.book_slug='revelation' AND tv.chapter_number=7 AND tv.verse_number=3
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_threads SET title = E'They which say they are Yahudim (Jews), and are not — the false-claim diagnostic, not a charter for replacement (Romans 2)', summary_md = E'This verse has been turned into a weapon against the covenant people, and the turning misreads what it says. *I know the blasphemy of them which say they are Yahudim (Jews), and are not, but are the synagogue of Satan* (Revelation 2:9). Read it as the Messiah speaks it: a false-claim diagnostic, not a charter for anti-Jewish replacement. The charge is on *the blasphemy* — the slander against the persecuted assembly — and on a claim to the covenant name held by those whose hearts oppose the name''s King. Paul holds exactly this measure: *he is not a Yahudi (Jew), which is one outwardly; neither is that circumcision, which is outward in the flesh* (Romans 2:28); *but he is a Yahudi (Jew), which is one inwardly; and circumcision is that of the heart, in the spirit, and not in the letter; whose praise is not of men, but of Elohim (God)* (Romans 2:29). The outward mark does not secure the name when the heart wars against the Messiah and his keepers. So *say they are Yahudim (Jews), and are not* is not the unmaking of the covenant, and it is not the handing of Yashar''el''s (Israel''s) name to some other people — it is the naming of the gap between a claimed name and a heart in opposition. The *synagogue of Satan* is his system — the adversary''s own assembly, built to wear the covenant name while warring on its keepers — and those who *say they are Yahudim (Jews), and are not* are the ones gathered into it. The true Yashar''el (Israel) is not erased here; it is the very seed being sealed and gathered later in the book — the twelve tribes named one by one, the great multitude gathered home. The false claim is exposed in this letter; the true seed is gathered in the chapters to come. To read the verse as a license for replacement is to make it deny the very gathering the book is moving toward.'
 WHERE slug='revelation-2-they-which-say-they-are-jews-and-are-not-the-false-claim-diagnostic-romans-2';

UPDATE cross_reference_threads SET title = E'The synagogue of Satan, which say they are Yahudim (Jews), and are not — the false-claim diagnostic (Isaiah 65)', summary_md = E'This is the verse the inherited reading has bent into a weapon against the Yahudim (Jews); read in the prophets'' own frame it is nothing of the kind. *Behold, I will make them of the synagogue of Satan, which say they are Yahudim (Jews), and are not, but do lie; behold, I will make them to come and worship before thy feet, and to know that I have loved thee* (Revelation 3:9). The charge is not against the people of Yahudah (Judah), whom the prophets gather home; it is against those who CLAIM the covenant name *and are not, but do lie* — who wear the name while opposing the Messiah and his commandment-keepers. The *synagogue of Satan* is his system, the adversary''s own assembly that clothes itself in the covenant name; the liars are those gathered into it. Isaiah drew exactly this line: not between Yahudi (Jew) and non-Yahudi, but between those who forsake Yahuah (LORD) and the servants he keeps. *Ye shall leave your name for a curse unto my chosen: for Adonai Yahuah (the Lord GOD) shall slay thee, and call his servants by another name* (Isaiah 65:15) — the rebels'' name becomes a curse, while the servants are called by a name of Yahuah''s (LORD''s) own giving, the new name promised to the overcomer at Philadelphia (Revelation 3:12). And Isaiah names the standard twice: the faithful bless and swear by *the Elohim (God) of truth* (Isaiah 65:16) — the very one who speaks here as *he that is holy, he that is true* (Revelation 3:7), the Amen who cannot lie. The false claimants *do lie*; they stand over against the Elohim (God) of truth. The reckoning is by truth, not by the bare word of the mouth — and the true word is settled by the calling, as Paul says: *I will call them my people, which were not my people; and her beloved, which was not beloved* (Romans 9:25). The people of Yahuah (LORD) are those he calls and loves, the scattered owned again as his own — not a people self-named by a claim the Messiah denies. So to the faithful the loving word is sealed: *I have loved thee.* This is a diagnostic of the false claim, never a charter for anti-Yahudi replacement; the true Yashar''el (Israel) is the one being gathered and sealed.'
 WHERE slug='revelation-3-the-synagogue-of-satan-which-say-they-are-jews-and-are-not-the-false-claim-isaiah-65';

UPDATE cross_reference_threads SET title = E'The scroll written within and on the backside, sealed with seven seals (Ezekiel 2, Isaiah 29, Daniel 12)', summary_md = E'John''s vision opens with a book no creature can open: *And I saw in the right hand of him that sat on the throne a book written within and on the backside, sealed with seven seals* (Revelation 5:1). The prophets saw the like. The roll itself is Ezekiel''s — *and, lo, a roll of a book was therein* (Ezekiel 2:9), and Ezekiel saw it just as John does: *it was written within and without: and there was written therein lamentations, and mourning, and woe* (Ezekiel 2:10) — a scroll crammed full on both faces, the overflowing decree of Yahuah (LORD). The sealing is Isaiah''s: *the vision of all is become unto you as the words of a book that is sealed, which men deliver to one that is learned, saying, Read this, I pray thee: and he saith, I cannot; for it is sealed* (Isaiah 29:11) — the helplessness John weeps over, *and no man in heaven, nor in earth, neither under the earth, was able to open the book* (Revelation 5:3). The learned cannot, the unlearned cannot; no creature can break it. And Daniel was shown the like, a witness to how Yahuah (LORD) keeps his counsel until its hour: *shut up the words, and seal the book, even to the time of the end* (Daniel 12:4). Here too the book stays shut, and John *wept much, because no man was found worthy* (Revelation 5:4) — until the elder names the One who can open it. *Weep not: behold, the Lion of the tribe of Juda, the Root of David, hath prevailed to open the book, and to loose the seven seals thereof* (Revelation 5:5). Ezekiel, Isaiah and Daniel stand as witnesses to a full and sealed word from the throne; Revelation itself names who breaks these seven seals — the slain Lamb alone is worthy to open the book.'
 WHERE slug='revelation-5-the-scroll-written-within-and-sealed-with-seven-seals-ezekiel-2';

UPDATE cross_reference_threads SET title = E'Ten thousand times ten thousand — the myriads before the throne (Daniel 7, 1 Enoch)', summary_md = E'Around the throne John hears a host beyond counting take up the praise of the Lamb: *And I beheld, and I heard the voice of many angels round about the throne and the beasts and the elders: and the number of them was ten thousand times ten thousand, and thousands of thousands* (Revelation 5:11). The count is Daniel''s, word for word: *thousand thousands ministered unto him, and ten thousand times ten thousand stood before him: the judgment was set, and the books were opened* (Daniel 7:10). Daniel saw the like before the Ancient of days, a witness to a heavenly court beyond counting; John now beholds such a host round about the throne, lifting its voice to the Lamb who has just taken the book. The same uncountable court appears in the Hebrew library''s throne-visions: *I saw thousands of thousands and myriads of myriads, and an infinite number of people, standing before Yahuah (God) of Spirits* (1 Enoch 40:1) — and Enoch heard their voices bless *Yahuah (God) of Spirits* and bless *the Elect One* beside him, the very pattern of Revelation 5, where the One on the throne and the Lamb are praised together. The throne-vision world of *ten thousand* reckonings runs through these texts (1 Enoch 14:21). And the host''s cry is the sevenfold acclamation: *Saying with a loud voice, Worthy is the Lamb that was slain to receive power, and riches, and wisdom, and strength, and honour, and glory, and blessing* (Revelation 5:12). The innumerable court that stood before the Father now lifts its voice to the slain Lamb.'
 WHERE slug='revelation-5-ten-thousand-times-ten-thousand-the-myriads-before-the-throne-daniel-7';

UPDATE cross_reference_threads SET title = E'The twelve tribes sealed — the two-house regathering, the two sticks made one (Ezekiel 37)', summary_md = E'The sealed company is named tribe by tribe, and the naming is the whole point: *And I heard the number of them which were sealed: and there were sealed an hundred and forty and four thousand of all the tribes of the children of Yashar''el (Israel)* (Revelation 7:4) — *Of the tribe of Juda were sealed twelve thousand* (Revelation 7:5), and so through *Joseph* and *Benjamin* (Revelation 7:8), the list naming Joseph and Manasses for the northern house. This is not a symbolic number that spiritualizes away the tribes and leaves a church standing in Yashar''el (Israel)''s place. It is the two-house gathering the prophet enacted with two sticks: *take thee one stick, and write upon it, For Yahudah (Judah), and for the children of Yashar''el (Israel) his companions: then take another stick, and write upon it, For Joseph, the stick of Ephraim, and for all the house of Yashar''el (Israel) his companions* (Ezekiel 37:16), *and join them one to another into one stick; and they shall become one in thine hand* (Ezekiel 37:17). Yahuah (LORD) says it plainly: *I will take the stick of Joseph, which is in the hand of Ephraim... even with the stick of Yahudah (Judah), and make them one stick, and they shall be one in mine hand* (Ezekiel 37:19). The tribes are sealed before the sifting, kept for the gathering that follows: *I will take the children of Yashar''el (Israel) from among the heathen, whither they be gone, and will gather them on every side, and bring them into their own land* (Ezekiel 37:21), *and I will make them one nation... and they shall be no more two nations, neither shall they be divided into two kingdoms any more at all* (Ezekiel 37:22). The 144,000 of all the tribes is Yahudah (Judah) and Ephraim/Joseph reunited — the two sticks become one in the hand of Yahuah (LORD), the divided houses sealed into one people. The restored library beholds the same numbered, sealed company gathered to the feast: *behold the number of those that be sealed in the feast of Yahuah (God)* (2 Esdras 2:38). Yashar''el (Israel) is not replaced; Yashar''el (Israel) is made whole.'
 WHERE slug='revelation-7-the-twelve-tribes-sealed-the-two-house-regathering-ezekiel-37';

UPDATE cross_reference_threads SET title = E'White robes and palms — the great Sukkot ingathering (Leviticus 23)', summary_md = E'The gathered multitude stands *clothed with white robes, and palms in their hands* (Revelation 7:9), and the palms are the palms of the feast of ingathering. At Sukkot Yashar''el (Israel) was commanded: *ye shall take you on the first day the boughs of goodly trees, branches of palm trees, and the boughs of thick trees, and willows of the brook; and ye shall rejoice before Yahuah Elohaychem (the LORD your God) seven days* (Leviticus 23:40) — the feast that remembers the wilderness journey and celebrates the gathering-in of the harvest. The regathered seed keeps the great Sukkot, palms in hand, rejoicing before the throne as the scattered seed is brought home from the nations. And the white robes are explained at the throne: *What are these which are arrayed in white robes? and whence came they?* (Revelation 7:13) — *These are they which came out of great tribulation, and have washed their robes, and made them white in the blood of the Lamb* (Revelation 7:14). The restored library names the same robed and palm-bearing company: *These be they that have put off the mortal clothing, and put on the immortal, and have confessed the name of Yahuah (God): now are they crowned, and receive palms* (2 Esdras 2:45). The white robes washed in the blood of the Lamb, the palms of the harvest feast — the homecoming of the seed kept as the everlasting Sukkot, rejoicing before Elohim (God).'
 WHERE slug='revelation-7-white-robes-and-palms-the-sukkot-ingathering-leviticus-23';

UPDATE cross_reference_threads SET title = E'The sun, moon, and stars a third darkened, and the threefold Woe — the darkness of Egypt and the day of Yahuah (Exodus 10, Joel 2, Isaiah 13)', summary_md = E'The fourth trumpet strikes the lights of heaven, and the eagle cries the threefold woe. *And the fourth angel sounded, and the third part of the sun was smitten, and the third part of the moon, and the third part of the stars; so as the third part of them was darkened, and the day shone not for a third part of it, and the night likewise* (Revelation 8:12). Its root is the ninth plague of Egypt: *And Yahuah (LORD) said unto Moses, Stretch out thine hand toward heaven, that there may be darkness over the land of Egypt, even darkness which may be felt* (Exodus 10:21), and *there was a thick darkness in all the land of Egypt three days* (Exodus 10:22). The darkness Moses brought over Pharaoh''s land now falls on the sun and moon and stars themselves. And the prophets had foreseen this darkening as the sign of the day of Yahuah (LORD): *The earth shall quake before them; the heavens shall tremble: the sun and the moon shall be dark, and the stars shall withdraw their shining* (Joel 2:10); *For the stars of heaven and the constellations thereof shall not give their light: the sun shall be darkened in his going forth, and the moon shall not cause her light to shine* (Isaiah 13:10). The very lights Joel and Isaiah said would fail in the day of wrath are smitten at the trumpet. Then *I beheld, and heard an angel flying through the midst of heaven, saying with a loud voice, Woe, woe, woe, to the inhabiters of the earth by reason of the other voices of the trumpet of the three angels, which are yet to sound* (Revelation 8:13) — four trumpets are spent, and the threefold woe warns that the worst of the day of Yahuah (LORD) is still to come upon the earth.'
 WHERE slug='revelation-8-the-sun-moon-and-stars-a-third-darkened-exodus-10-joel-2';

UPDATE cross_reference_threads SET title = E'The fallen star and the key of the bottomless pit, the smoke as of a great furnace (Genesis 19, Isaiah 14, 1 Enoch 18)', summary_md = E'The fifth trumpet opens on a fall and an unlocking: *And the fifth angel sounded, and I saw a star fall from heaven unto the earth: and to him was given the key of the bottomless pit. And he opened the bottomless pit; and there arose a smoke out of the pit, as the smoke of a great furnace; and the sun and the air were darkened by reason of the smoke of the pit* (Revelation 9:1-2). Every image here the seer draws from the older library. The pit is the one Isaiah named in the proverb taken up *against the king of Babylon* (Isaiah 14:4): *How art thou fallen from heaven, O Lucifer, son of the morning! how art thou cut down to the ground* (Isaiah 14:12) — Babel''s king, who said *I will ascend into heaven, I will exalt my throne above the stars of Elohim (God)* (Isaiah 14:13) and was answered, *Yet thou shalt be brought down to hell, to the sides of the pit* (Isaiah 14:15). The star is given the key; the chamber it opens is the one where Babel''s king was laid, and out of it the king of the locusts rises. And the smoke is Sodom''s smoke: Abraham *looked toward Sodom and Gomorrah... and, lo, the smoke of the country went up as the smoke of a furnace* (Genesis 19:28) — the oldest furnace of judgment in the Torah, now rising from the pit to darken the sun. The Hebrew library names the very chamber unlocked. Enoch was shown a waste place at the end of heaven and earth — *this has become a prison for the stars and the host of heaven* (1 Enoch 18:12) — the transgressing stars *bound... till the time when their guilt should be consummated* (1 Enoch 18:14), an abyss *cleft as far as the abyss, being full of great descending columns of fire* (1 Enoch 21:8). And he saw the fallen star itself seized and *cast into an abyss... narrow and deep, and horrible and dark* (1 Enoch 88:1). The fallen star, the prison-pit, the furnace-fire are one architecture across the witnesses; the trumpet only sounds the appointed hour at which the long-bound mouth is opened.'
 WHERE slug='revelation-9-the-fallen-star-and-the-key-of-the-bottomless-pit-the-smoke-of-the-furnace-genesis-19-isaiah-14';

UPDATE cross_reference_threads SET title = E'Abaddon, Apollyon — the angel of the bottomless pit (Job 26, Proverbs 15, Psalm 88, 1 Enoch 10)', summary_md = E'The swarm has a sovereign: *And they had a king over them, which is the angel of the bottomless pit, whose name in the Hebrew tongue is Abaddon, but in the Greek tongue hath his name Apollyon* (Revelation 9:11). The Hebrew name is no invention — it is a word the Tanakh already carried for the realm of ruin. Job pairs it with death and the grave: *Hell is naked before him, and destruction hath no covering* (Job 26:6), and *Destruction and death say, We have heard the fame thereof with our ears* (Job 28:22) — Abaddon as the deep power that stands at the farthest remove from wisdom and light. The Proverbs set it under the eye of the Most High: *Hell and destruction are before Yahuah (LORD): how much more then the hearts of the children of men?* (Proverbs 15:11) — Abaddon is not a rival throne but a chamber laid open before Yahuah (LORD). And the psalmist names it the lightless place where praise is not heard: *Shall thy lovingkindness be declared in the grave? or thy faithfulness in destruction?* (Psalm 88:11). The king of the locusts bears the name of Destruction itself. And the Hebrew library knows the pit as a prison: Yahuah (God) said to Raphael, *Bind Azâzêl hand and foot, and cast him into the darkness* (1 Enoch 10:4) — a witness that the deep holds its bound ones until judgment. Yet the king of the locusts is not the one cast down from heaven. He is Babel''s king, Nimrod, whose kingdom began at Babel — the one the dragon raises up, ruling from the underworld, the beast out of the pit that *was, and is not; and shall ascend out of the bottomless pit, and go into perdition* (Revelation 17:8). Even Abaddon stands before Yahuah (LORD), and its king rises only at the trumpet''s appointed hour.'
 WHERE slug='revelation-9-abaddon-apollyon-the-angel-of-the-bottomless-pit-job-26-proverbs-15-psalm-88';

UPDATE cross_reference_threads SET title = E'The mighty angel clothed with a cloud, the rainbow, and the pillars of fire (Ezekiel 1)', summary_md = E'John sees *another mighty angel come down from heaven, clothed with a cloud: and a rainbow was upon his head, and his face was as it were the sun, and his feet as pillars of fire* (Revelation 10:1), and *he had in his hand a little book open: and he set his right foot upon the sea, and his left foot on the earth* (Revelation 10:2). Every feature is drawn from the Tanakh''s theophany-glory. The rainbow set in the cloud is the crown of Ezekiel''s throne-vision — *As the appearance of the bow that is in the cloud in the day of rain, so was the appearance of the brightness round about. This was the appearance of the likeness of the glory of Yahuah (LORD)* (Ezekiel 1:28) — and the man-likeness enthroned above the firmament, *upon the likeness of the throne was the likeness as the appearance of a man above upon it* (Ezekiel 1:26), is the glory that holds dominion over the whole creation, now bending down with the open book. Daniel saw the like by the great river, a man clothed in linen — *his face as the appearance of lightning, and his eyes as lamps of fire, and his arms and his feet like in colour to polished brass* (Daniel 10:6) — sent *to make thee understand what shall befall thy people in the latter days* (Daniel 10:14). Daniel stands as a witness that Elohim (God) clothes his messengers in fire and light; Revelation tells of its own mighty angel. And the cloud and the pillar of fire are the Exodus presence itself: *Yahuah (LORD) went before them by day in a pillar of a cloud, to lead them the way; and by night in a pillar of fire, to give them light* (Exodus 13:21). The glory that led the redeemed out of bondage now stands astride the sea and the land, the same presence overshadowing the new exodus the Apocalypse unfolds. John is no inventor of strange sights; he sees with Ezekiel''s and Daniel''s and Moses'' eyes, and the mighty angel wears the one unbroken glory of Yahuah (LORD).'
 WHERE slug='revelation-10-the-mighty-angel-clothed-with-a-cloud-the-rainbow-and-the-pillars-of-fire-ezekiel-1';

UPDATE cross_reference_threads SET title = E'The angel''s oath by him that liveth for ever, who created heaven, earth, and sea (Deuteronomy 32 and Daniel 12)', summary_md = E'*And the angel which I saw stand upon the sea and upon the earth lifted up his hand to heaven, and sware by him that liveth for ever and ever, who created heaven, and the things that therein are, and the earth, and the things that therein are, and the sea, and the things which are therein, that there should be time no longer* (Revelation 10:5-6). The oath is the Tanakh''s own. The raised hand and the swearing-formula are the Song of Moses, where Yahuah (LORD) himself swears: *For I lift up my hand to heaven, and say, I live for ever* (Deuteronomy 32:40). Daniel was shown the like, and stands here as a witness: *I heard the man clothed in linen, which was upon the waters of the river, when he held up his right hand and his left hand unto heaven, and sware by him that liveth for ever that it shall be for a time, times, and an half; and when he shall have accomplished to scatter the power of the holy people, all these things shall be finished* (Daniel 12:7) — the figure upon the waters, the lifted hand, the oath *by him that liveth for ever,* and the declaration that *all these things shall be finished,* while Daniel''s measure stays in Daniel and John''s next verse speaks Revelation''s own finishing: *the mystery of Elohim (God) should be finished* (Revelation 10:7). And the One sworn by is named by the threefold creation-confession of the Levites'' great prayer of return: *Thou, even thou, art Yahuah (LORD) alone; thou hast made heaven, the heaven of heavens, with all their host, the earth, and all things that are therein, the seas, and all that is therein, and thou preservest them all; and the host of heaven worshippeth thee* (Nehemiah 9:6). The oath is sworn by the Creator alone — heaven, earth, sea, and all therein his — the One whom the host of heaven worships. Worship and oath alike belong to the Maker of all, and by him the consummation is sworn.'
 WHERE slug='revelation-10-the-angels-oath-by-him-that-liveth-for-ever-deuteronomy-32-and-daniel-12';

UPDATE cross_reference_threads SET title = E'The two witnesses, the two olive trees and the two candlesticks standing before the Elohim (God) of the earth (Zechariah 4)', summary_md = E'The two witnesses are named straight out of Zechariah''s lampstand vision: *And I will give power unto my two witnesses, and they shall prophesy a thousand two hundred and threescore days, clothed in sackcloth. These are the two olive trees, and the two candlesticks standing before the Elohim (God) of the earth* (Revelation 11:3-4). Zechariah saw the golden candlestick with its seven lamps, and *two olive trees by it, one upon the right side of the bowl, and the other upon the left side thereof* (Zechariah 4:3), feeding it oil. He asked, *What are these two olive trees upon the right side of the candlestick and upon the left side thereof?* (Zechariah 4:11), and the answer is the seer''s own: *These are the two anointed ones, that stand by Yahuah (Lord) of the whole earth* (Zechariah 4:14). The witnesses stand where the anointed stand — before the Lord of the whole earth — and bear his light through the thousand two hundred and threescore days of their prophecy in the reign, carrying the word Zechariah heard: *Not by might, nor by power, but by my spirit, saith Yahuah Tseva''ot (LORD of hosts)* (Zechariah 4:6). Two witnesses, the two houses, Yahudah (Judah) and Yashar''el (Israel), for by two the testimony is established; the lamps of Yahuah (LORD) burning before him, supplied by the oil of his Spirit, prophesying the whole appointed time.'
 WHERE slug='revelation-11-the-two-witnesses-the-two-olive-trees-and-the-two-candlesticks-zechariah-4';

UPDATE cross_reference_threads SET title = E'Fire out of their mouth, power to shut heaven and to turn the waters to blood — the two houses in the pattern of Moses and Elijah (1 Kings 17, Exodus 7)', summary_md = E'The two witnesses, the two houses, Yahudah (Judah) and Yashar''el (Israel), carry gifts after the pattern of the two greatest prophets — Moses and Elijah, the law and the prophets. *And if any man will hurt them, fire proceedeth out of their mouth, and devoureth their enemies* (Revelation 11:5): this is the word Yahuah (LORD) put in Jeremiah''s mouth — *behold, I will make my words in thy mouth fire, and this people wood, and it shall devour them* (Jeremiah 5:14) — the prophetic word itself made fire. It is Elijah''s fire too, who said to the captains sent to seize him, *let fire come down from heaven, and consume thee and thy fifty. And there came down fire from heaven, and consumed him and his fifty* (2 Kings 1:10). *These have power to shut heaven, that it rain not in the days of their prophecy* (Revelation 11:6) — the very word of the Tishbite: *there shall not be dew nor rain these years, but according to my word* (1 Kings 17:1). *And have power over waters to turn them to blood, and to smite the earth with all plagues, as often as they will* (Revelation 11:6) — the sign of Moses: *I will smite with the rod that is in mine hand upon the waters which are in the river, and they shall be turned to blood* (Exodus 7:17). The Hebrew library kept the memory of Elijah as fire himself — *Then stood up Elias the prophet as fire, and his word burned like a lamp* (Sirach 48:1), who *by the word of Yahuah (God)... shut up the heaven, and also three times brought down fire* (Sirach 48:3). So the two candlesticks burn: the fire of Elijah and the smitten waters of Moses are the pattern of their gifts, not the names of the witnesses; the two houses testify together in the power of the law and the prophets through the thousand two hundred and threescore days of the reign.'
 WHERE slug='revelation-11-fire-out-of-their-mouth-and-power-over-heaven-moses-and-elijah-1-kings-17';

UPDATE cross_reference_threads SET title = E'The beast from the pit makes war and slays them; their bodies in the great city spiritually called Sodom (Daniel 7, Isaiah 1)', summary_md = E'When the testimony of the reign is finished, in the little season after it, the beast out of the pit prevails for a season: *And when they shall have finished their testimony, the beast that ascendeth out of the bottomless pit shall make war against them, and shall overcome them, and kill them* (Revelation 11:7). Daniel was shown the like — *the same horn made war with the saints, and prevailed against them* (Daniel 7:21) — a witness to the pattern, not the key to this beast: war on the saints always ends in the verdict, *until the Ancient of days came, and judgment was given to the saints* (Daniel 7:22). So here the prevailing of the beast out of the pit is brief, and the slain witnesses rise at the last trump. The bodies of the witnesses lie unburied *in the street of the great city, which spiritually is called Sodom and Egypt, where also our Lord was crucified* (Revelation 11:8), while the peoples gaze and the earth-dwellers make merry over them. The name *Sodom* is the prophets'' own charge against the covenant city in her rebellion: Isaiah cried, *Except Yahuah Tseva''ot (LORD of hosts) had left unto us a very small remnant, we should have been as Sodom, and we should have been like unto Gomorrah* (Isaiah 1:9), and named her rulers outright — *Hear the word of Yahuah (LORD), ye rulers of Sodom; give ear unto the law of our Elohim (God), ye people of Gomorrah* (Isaiah 1:10). Sodom for her wickedness, Egypt for her bondage — the city that slew the prophets and crucified the Lord earns the name not by her place but by her deeds. The witnesses fall where the Master fell; but as with him, the killing is not the end.'
 WHERE slug='revelation-11-the-beast-from-the-pit-slays-them-in-the-great-city-called-sodom-daniel-7';

UPDATE cross_reference_threads SET title = E'The Spirit of life entered them and they stood upon their feet, and ascended in a cloud (Ezekiel 37, 2 Kings 2)', summary_md = E'The slain witnesses are raised, and the raising is Ezekiel''s valley of dry bones: *And after three days and an half the Spirit of life from Elohim (God) entered into them, and they stood upon their feet; and great fear fell upon them which saw them* (Revelation 11:11). Yahuah (LORD) said over the bones, *Behold, I will cause breath to enter into you, and ye shall live* (Ezekiel 37:5), and *the breath came into them, and they lived, and stood up upon their feet, an exceeding great army* (Ezekiel 37:10) — the very words, *stood up upon their feet.* And Ezekiel told what the raising meant: *these bones are the whole house of Yashar''el (Israel)* (Ezekiel 37:11), the graves opened and the people brought home — so the standing witnesses are the righteous rising at the great resurrection. Then the ascent: *And they heard a great voice from heaven saying unto them, Come up hither. And they ascended up to heaven in a cloud; and their enemies beheld them* (Revelation 11:12). Elijah''s going-up is its pattern — *Elijah went up by a whirlwind into heaven* (2 Kings 2:11) — and the library kept the memory: *Who was taken up in a whirlwind of fire, and in a chariot of fiery horses* (Sirach 48:9). The same passage names why the prophet was kept: he was *ordained for reproofs in their times... and to restore the tribes of Jacob* (Sirach 48:10). The witnesses, the two houses, Yahudah (Judah) and Yashar''el (Israel), walk in that office, and their *Come up hither* is the catching-up Paul named: *Then we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord* (1 Thessalonians 4:17) — after the reign and the little season, at the last trump, when the righteous rise at the great resurrection.'
 WHERE slug='revelation-11-the-spirit-of-life-entered-them-and-they-ascended-in-a-cloud-ezekiel-37';

UPDATE cross_reference_threads SET title = E'The kingdoms of this world are become the kingdoms of our Lord, and of his Messiah (Christ) (Daniel 2 and 7, Psalm 2)', summary_md = E'The seventh trumpet sounds the heart of the whole vision: *And the seventh angel sounded; and there were great voices in heaven, saying, The kingdoms of this world are become the kingdoms of our Lord, and of his Messiah (Christ); and he shall reign for ever and ever* (Revelation 11:15). This is the stone Daniel saw shatter the image of the kingdoms: *in the days of these kings shall the Elohim (God) of heaven set up a kingdom, which shall never be destroyed... and it shall stand for ever* (Daniel 2:44). It is the dominion given to the one *like the Son of Adam*: *there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion* (Daniel 7:14) — the kingdom *of his Messiah (Christ)*, the Formed Son receiving from the Father the everlasting reign. Zechariah saw the same kingship open the reign, and here the last trump declares it complete — *Yahuah (LORD) shall be king over all the earth: in that day shall there be one Yahuah (LORD), and his name one* (Zechariah 14:9) — and the song of the sea come round at last — *Yahuah (LORD) shall reign for ever and ever* (Exodus 15:18). So the elders fall and give thanks: *We give thee thanks, O Yahuah Elohim (Lord God) Almighty, which art, and wast, and art to come; because thou hast taken to thee thy great power, and hast reigned* (Revelation 11:17). The Father gave his anointed *the heathen for thine inheritance* (Psalm 2:8) and the rod to *dash them in pieces* (Psalm 2:9); so *the nations were angry, and thy wrath is come... and shouldest destroy them which destroy the earth* (Revelation 11:18), and with it *the time of the dead, that they should be judged* (Revelation 11:18), the one judgment of the dead, the same reckoning shown again at the white throne (Revelation 20:11-15); and the reward is given to the saints — for the kingdom *shall be given to the people of the saints of the El Elyon (most High), whose kingdom is an everlasting kingdom* (Daniel 7:27). The trumpet that crowns the Messiah crowns his people with him, and the everlasting reign foretold from the exodus to Daniel is declared come.'
 WHERE slug='revelation-11-the-kingdoms-become-the-kingdoms-of-our-lord-and-of-his-messiah-daniel-2-7';

UPDATE cross_reference_threads SET title = E'The woman clothed with the sun — Yashar''el (Israel), the northern company, in travail (Genesis 37)', summary_md = E'*And there appeared a great wonder in heaven; a woman clothed with the sun, and the moon under her feet, and upon her head a crown of twelve stars* (Revelation 12:1). The signs are Joseph''s dream: *behold, the sun and the moon and the eleven stars made obeisance to me* (Genesis 37:9) — the sun and moon Jacob and Rachel, the stars the sons, and the dream is Joseph''s, head of the northern house. The woman is Yashar''el (Israel), the northern company, no new thing and no replacement people; she is the covenant family of the promise, clothed in the lights of heaven, carrying the seed. And she travails: *she being with child cried, travailing in birth, and pained to be delivered* (Revelation 12:2). The prophets had drawn this woman long before. Isaiah was shown the like in Zion, whose desolation turns to a multitude — *Sing, O barren, thou that didst not bear; break forth into singing, and cry aloud, thou that didst not travail with child: for more are the children of the desolate than the children of the married wife* (Isaiah 54:1) — the wife of Yahuah (LORD) himself: *thy Maker is thine husband; Yahuah Tseva''ot (LORD of hosts) is his name; and thy Redeemer the Holy One of Yashar''el (Israel)* (Isaiah 54:5). And Micah was shown the labouring daughter of Zion, brought through exile to deliverance, a witness to the pattern: *Be in pain, and labour to bring forth, O daughter of Zion, like a woman in travail... there shalt thou be delivered; there Yahuah (LORD) shall redeem thee from the hand of thine enemies* (Micah 4:10). The pangs are real; the deliverance is sure. The woman in labour is the covenant people bringing forth, out of her affliction, the seed of promise.'
 WHERE slug='revelation-12-the-woman-clothed-with-the-sun-the-travail-of-zion-genesis-37';

UPDATE cross_reference_threads SET title = E'Michael and his angels fought against the dragon — the prince who standeth for the people (Daniel 10 and 12)', summary_md = E'*And there was war in heaven: Michael and his angels fought against the dragon; and the dragon fought and his angels, And prevailed not; neither was their place found any more in heaven* (Revelation 12:7-8). Michael is the warrior Daniel was shown — the unseen battle behind the kingdoms of the earth. *Lo, Michael, one of the chief princes, came to help me* (Daniel 10:13); he is named *your prince* (Daniel 10:21), the prince set for the covenant people; and his rising is the deliverance of that people: *And at that time shall Michael stand up, the great prince which standeth for the children of thy people... and at that time thy people shall be delivered, every one that shall be found written in the book* (Daniel 12:1). Daniel was shown the like: Michael stands, and the people are delivered. Here the dragon is cast down, but his war is not finished — *the dragon was wroth with the woman, and went to make war with the remnant of her seed* (Revelation 12:17), until the reign; the deliverance comes at the end of that war. The restored library remembers the same Michael at the same office, the appointed binder of the rebel powers: *And Yahuah (God) said unto Michael: ''Go, bind Semjâzâ and his associates''* (1 Enoch 10:11); *Michael, one of the holy and honoured angels, who is set over the best part of mankind and over chaos* (1 Enoch 20:5). Set over the best part of mankind — the people of the promise — and over chaos: that is exactly his work in the vision, the guardian of the woman warring against the chaos-serpent who would devour her child.'
 WHERE slug='revelation-12-michael-and-his-angels-fought-against-the-dragon-daniel-10-and-12';

UPDATE cross_reference_threads SET title = E'The beast out of the sea — seven heads and ten horns, with Daniel as witness (Daniel 7)', summary_md = E'John stands on the sand and sees *a beast rise up out of the sea, having seven heads and ten horns, and upon his horns ten crowns, and upon his heads the name of blasphemy* (Revelation 13:1), and Daniel was shown the like. There *four great beasts came up from the sea, diverse one from another* (Daniel 7:3) — and John''s one beast out of the sea bears features Daniel saw spread across them: *the beast which I saw was like unto a leopard, and his feet were as the feet of a bear, and his mouth as the mouth of a lion* (Revelation 13:2). The leopard is Daniel''s third beast (*lo another, like a leopard*, Daniel 7:6), the bear his second (*like to a bear*, Daniel 7:5), the lion his first (*the first was like a lion*, Daniel 7:4) — features of three beasts in the body, feet, and mouth of the beast out of the sea. And the ten horns Daniel saw on the dreadful fourth: *a fourth beast, dreadful and terrible... and it had ten horns* (Daniel 7:7), *the fourth kingdom upon earth... [that] shall devour the whole earth* (Daniel 7:23). The like world-wide reach John sees given the beast out of the sea — *power was given him over all kindreds, and tongues, and nations* (Revelation 13:7). The restored library keeps the same vision: Ezra too saw *come up from the sea an eagle, which had twelve feathered wings, and three heads* (2 Esdras 11:1), reigning over all the earth, and the interpreting voice told him plainly, *The eagle, whom you sawest come up from the sea, is the kingdom which was seen in the vision of your brother Daniel* (2 Esdras 12:11). Three seers, three visions, each read in its own book: Daniel and Ezra witness to the kind of thing John sees, kingdoms that rise from the troubled sea of the nations; they do not decide what John''s beast out of the sea is. And *the dragon gave him his power, and his seat, and great authority* (Revelation 13:2). This is no new thing under the sun, and its end is written in Revelation itself: the beast out of the sea and the false prophet *were cast alive into a lake of fire burning with brimstone* (Revelation 19:20), before the reign.'
 WHERE slug='revelation-13-the-beast-from-the-sea-the-four-beasts-of-daniel-gathered-into-one';

UPDATE cross_reference_threads SET title = E'A mouth speaking great things, forty and two months, war with the saints (Daniel 7)', summary_md = E'*And there was given unto him a mouth speaking great things and blasphemies; and power was given unto him to continue forty and two months* (Revelation 13:5). Daniel was shown the like, and his words stand beside it as witness. The *mouth speaking great things* is the little horn''s — *in this horn were eyes like the eyes of man, and a mouth speaking great things* (Daniel 7:8). The *forty and two months* is Revelation''s own measure for the beast out of the sea, kept in its own unit and not traded for Daniel''s. And Daniel 7:25 witnesses to the same character in the horn Daniel saw: *he shall speak great words against the El Elyon (most High), and shall wear out the saints of the El Elyon (most High), and think to change times and laws.* This is the heart of it — the beast-system makes war on the commandments of Yahuah (LORD), reaching to alter the very times and laws he appointed, and that is the blasphemy John names when the beast *opened his mouth in blasphemy against Elohim (God), to blaspheme his name, and his tabernacle* (Revelation 13:6). The self-exalting king of Daniel 11 is of the same spirit: he *shall magnify himself above every god, and shall speak marvellous things against the Elohim (God) of gods* (Daniel 11:36). And the war is real — *it was given unto him to make war with the saints, and to overcome them* (Revelation 13:7), as Daniel was shown the like — *the same horn made war with the saints, and prevailed against them* (Daniel 7:21). But the overcoming is bounded twice over: bounded in time to the forty-and-two months, as Daniel''s king was bounded *till the indignation be accomplished* (Daniel 11:36); and bounded in outcome, for Daniel saw past it — *until the Ancient of days came, and judgment was given to the saints of the El Elyon (most High); and the time came that the saints possessed the kingdom* (Daniel 7:22). The mouth is loud, but the clock is the Father''s, and the verdict is already given for the saints.'
 WHERE slug='revelation-13-a-mouth-speaking-great-things-and-blasphemies-forty-and-two-months';

UPDATE cross_reference_threads SET title = E'One sat like unto the Son of Adam on the white cloud — the kaph preserved (Daniel 7, Revelation 1, 1 Enoch 46-62)', summary_md = E'*And I looked, and behold a white cloud, and upon the cloud one sat like unto the Son of Adam, having on his head a golden crown, and in his hand a sharp sickle* (Revelation 14:14). Daniel was shown the like in his night vision, a witness to the same cloud-rider: *behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days* (Daniel 7:13). The kaph — the *like* — is preserved in both, and it does its own work: he is *like* the Son of Adam, not a bare title flattened, but the One who resembles a son of mortal-man because he took on flesh, while remaining the Formed cloud-rider who comes to the Ancient of days. The golden crown upon him is the kingdom Daniel saw given; the cloud is his own, for the cloud-rider is consistently the divine One across the scriptures. And he is the same figure John saw at the first — *one like unto the Son of Adam* in the midst of the lampstands (Revelation 1:13) — the One who *was dead, and is alive for evermore.* The Gospels name his coming in the same words: *they shall see the Son of Adam coming in the clouds of heaven with power and great glory* (Matthew 24:30); *they shall see the Son of Adam coming in the clouds with great power and glory* (Mark 13:26) — all re-speaking Daniel 7. And the restored library carries the same vision: beside the Head of Days stood *another being whose countenance had the appearance of a man* (1 Enoch 46:1), and the angel named him — *this is the Son of Adam who hath righteousness, with whom dwelleth righteousness... because Yahuah (God) of Spirits hath chosen him* (1 Enoch 46:3); *that Son of Adam was named In the presence of Yahuah (God) of Spirits... before the sun and the signs were created* (1 Enoch 48:2-3); *this is the Son of Adam who is born unto righteousness, And righteousness abides over him* (1 Enoch 62:7). When scripture is brought to bear on scripture, the One crowned upon the white cloud lands as Yahusha (Jesus) himself — the Formed cloud-rider, named before the foundation of the world, chosen and hidden and revealed, who took on flesh and remains who he was, and is, and is to come, enthroned now over the harvest of the earth.'
 WHERE slug='revelation-14-one-sat-like-unto-the-son-of-adam-on-the-white-cloud-daniel-7';

UPDATE cross_reference_threads SET title = E'The harvest of the earth and the winepress of wrath trodden (Joel 3, Isaiah 63, Lamentations 1, 2 Esdras 4)', summary_md = E'The reaping comes in two figures, both the prophets'': the harvest of the grain and the treading of the grapes. *Thrust in thy sickle, and reap: for the time is come for thee to reap; for the harvest of the earth is ripe* (Revelation 14:15) — the angel cries the prophet''s own command, *Put ye in the sickle, for the harvest is ripe... for the press is full, the fats overflow; for their wickedness is great* (Joel 3:13). And the restored library names this reaping the threshing-time: *the grain of evil seed has been sown in the heart of Adam from the beginning... how much shall it yet bring forth until the time of threshing come?* (2 Esdras 4:30); *when the ears shall be cut down, which are without number, how great a floor shall they fill?* (2 Esdras 4:32) — so *the earth was reaped* (Revelation 14:16), the floor filled with the ears of the evil seed — the tares cut down first, the sickle and the winepress both falling on the wicked. Then the second figure: the vine of the earth gathered and *cast it into the great winepress of the wrath of Elohim (God)* (Revelation 14:19), the winepress Isaiah saw trodden — *I have trodden the winepress alone; and of the people there was none with me: for I will tread them in mine anger* (Isaiah 63:3); *I will tread down the people in mine anger, and make them drunk in my fury* (Isaiah 63:6). It is the day of vengeance, the One who comes from Edom with dyed garments. *And the winepress was trodden without the city, and blood came out of the winepress, even unto the horse bridles* (Revelation 14:20) — the treading that once fell on the unfaithful city, *Yahuah (Lord) hath trodden the virgin, the daughter of Yahudah (Judah), as in a winepress* (Lamentations 1:15), poured out at the last upon the vine ripe for wrath; and the blood rising to the horse bridles is the measure the restored library gave: *the horse shall walk up to the breast in the blood of sinners* (1 Enoch 100:3). One vision of the great day when the wickedness of the earth is trodden out in the fury of Yahuah (LORD).'
 WHERE slug='revelation-14-the-harvest-of-the-earth-and-the-winepress-of-wrath-joel-3-isaiah-63';

UPDATE cross_reference_threads SET title = E'The noisome and grievous sore on them that bear the mark — the boils of Egypt (Exodus 9)', summary_md = E'The first vial opens the seven bowls by reaching straight back to Egypt: *there fell a noisome and grievous sore upon the men which had the mark of the beast, and upon them which worshipped his image* (Revelation 16:2). This is the sixth plague re-spoken — *a boil breaking forth with blains upon man, and upon beast, throughout all the land of Egypt* (Exodus 9:9), the boil so grievous that *the magicians could not stand before Moses because of the boils; for the boil was upon the magicians, and upon all the Egyptians* (Exodus 9:11). The same Yahuah (LORD) who plagued Pharaoh''s land now plagues the kingdom of the beast, and he strikes by the very mark: the sore falls on those who took the mark of the beast out of the sea in thought and in deed, the forehead and the hand, none able to stand. And the covenant had named this sanction long before — *Yahuah (LORD) shall smite thee... with a sore botch that cannot be healed, from the sole of thy foot unto the top of thy head* (Deuteronomy 28:35), the unhealable botch set against those who forsake him. They who took the mark of the false lord inherit the curse of Egypt and the curse of the covenant together. The new exodus judges the new Egypt by the old sign.'
 WHERE slug='revelation-16-the-noisome-sore-on-them-that-bear-the-mark-the-boils-of-egypt-exodus-9';

UPDATE cross_reference_threads SET title = E'The Euphrates dried for the kings of the east, the way prepared (Isaiah 11)', summary_md = E'The sixth vial dries the great river: *the sixth angel poured out his vial upon the great river Euphrates; and the water thereof was dried up, that the way of the kings of the east might be prepared* (Revelation 16:12). The drying re-speaks the second exodus Isaiah foresaw — when *Yahuah (LORD) shall utterly destroy the tongue of the Egyptian sea; and with his mighty wind shall he shake his hand over the river, and shall smite it in the seven streams, and make men go over dryshod* (Isaiah 11:15), making *an highway for the remnant of his people... like as it was to Yashar''el (Israel) in the day that he came up out of the land of Egypt* (Isaiah 11:16). The kings of the east are that remnant: the gathered seed coming home from the lands of the scattering beyond the river, the highway theirs — as the restored library saw, *the Highest shall stay the springs of the stream again, that they may go through* (2 Esdras 13:47). Judgment and gathering are bound in one act. And it is Babylon''s own doom: Jeremiah foretold *a drought... upon her waters; and they shall be dried up: for it is the land of graven images* (Jeremiah 50:38), and Yahuah (LORD) swore, *I will dry up her sea, and make her springs dry* (Jeremiah 51:36). The river that was Babylon''s defence and her boast is dried at the word of Yahuah (LORD), and the river that was her wall becomes the road home for the seed she held among the nations.'
 WHERE slug='revelation-16-the-euphrates-dried-for-the-kings-of-the-east-the-way-prepared-isaiah-11';

UPDATE cross_reference_threads SET title = E'I come as a thief; blessed is he that keepeth his garments; and Armageddon, the battle of Zechariah 14 (Zechariah 3, 12, 14)', summary_md = E'Into the gathering of the kings the voice of Yahusha (Jesus) breaks in mid-judgment: *Behold, I come as a thief. Blessed is he that watcheth, and keepeth his garments, lest he walk naked, and they see his shame* (Revelation 16:15). To keep the garments is to keep the cleansed robe Yahuah (LORD) gives — as Joshua the high priest stood *clothed with filthy garments*, and the angel commanded, *Take away the filthy garments from him... I have caused thine iniquity to pass from thee, and I will clothe thee with change of raiment* (Zechariah 3:4). It is the call to Zion, *Awake, awake; put on thy strength, O Zion; put on thy beautiful garments, O Jerusalem, the holy city* (Isaiah 52:1): to be found watchful and clothed, not stripped and shamed, when the Master comes unlooked-for as a thief. Then the kings are mustered: *he gathered them together into a place called in the Hebrew tongue Armageddon* (Revelation 16:16) — har-Megiddo, the mountain of Megiddo. Zechariah named the ground: *a great mourning in Jerusalem, as the mourning of Hadadrimmon in the valley of Megiddon* (Zechariah 12:11). It is the field where *the kings came and fought... by the waters of Megiddo* and the stars in their courses broke them (Judges 5:19), and where good Josiah fell, *he slew him at Megiddo* (2 Kings 23:29). The name soaked in the memory of kings cut down is set on the battle at the front edge of the Day, the battle Zechariah saw: *For I will gather all nations against Jerusalem to battle... Then shall Yahuah (LORD) go forth, and fight against those nations, as when he fought in the day of battle. And his feet shall stand in that day upon the mount of Olives* (Zechariah 14:2-4). Armageddon is that day — and over it stands the warning to watch and keep the garments, for he comes as a thief.'
 WHERE slug='revelation-16-i-come-as-a-thief-blessed-is-he-that-keepeth-his-garments-and-armageddon-zechariah-3-12';

UPDATE cross_reference_threads SET title = E'It is done — the great earthquake and the great hail (Ezekiel 38, Isaiah 66)', summary_md = E'The seventh vial finishes the wrath. *The seventh angel poured out his vial into the air; and there came a great voice out of the temple of heaven, from the throne, saying, It is done* (Revelation 16:17). Isaiah had heard that voice: *a voice from the temple, a voice of Yahuah (LORD) that rendereth recompence to his enemies* (Isaiah 66:6) — the voice of recompence declaring the bowls poured to the last. Then the shaking and the hail. *There was a great earthquake, such as was not since men were upon the earth, so mighty an earthquake, and so great* (Revelation 16:18); Ezekiel foretold it of the day of Gog — *in my jealousy and in the fire of my wrath have I spoken, Surely in that day there shall be a great shaking in the land of Yashar''el (Israel)* (Ezekiel 38:19) — and Daniel of the end — *a time of trouble, such as never was since there was a nation* (Daniel 12:1), in which *thy people shall be delivered, every one that shall be found written in the book*, the watchful keepers of the garments. And the great city is divided, *great Babylon came in remembrance before Elohim (God), to give unto her the cup of the wine of the fierceness of his wrath* (Revelation 16:19). Last falls the seventh plague of Egypt poured out full: *there fell upon men a great hail out of heaven, every stone about the weight of a talent: and men blasphemed Elohim (God) because of the plague of the hail; for the plague thereof was exceeding great* (Revelation 16:21). Egypt had known *hail, and fire mingled with the hail, very grievous, such as there was none like it* (Exodus 9:24); Yahuah (LORD) had sworn to rain on Gog *great hailstones, fire, and brimstone* (Ezekiel 38:22); and the Hebrew library remembered how *the ungodly, that denied to know* him were persecuted *with strange rains, hails, and showers... and through fire were they consumed* (Wisdom 16:16). The unequalled hail falls on the world of the beast — and still the men blaspheme and will not repent. The wrath at the front edge of the Day is done; the ground is cleared for the reign.'
 WHERE slug='revelation-16-it-is-done-the-great-earthquake-and-the-great-hail-ezekiel-38-isaiah-66';

UPDATE cross_reference_threads SET title = E'The woman on the scarlet beast, seven heads and ten horns — the beast out of the pit (Revelation 17:8; Daniel 7)', summary_md = E'*I saw a woman sit upon a scarlet coloured beast, full of names of blasphemy, having seven heads and ten horns* (Revelation 17:3). The angel names this beast himself: it is the beast that *was, and is not; and shall ascend out of the bottomless pit* (Revelation 17:8) — the beast out of the pit, not the beast out of the sea of 13:1. Daniel was shown the like in his night-vision, a witness only: he saw *four great beasts came up from the sea, diverse one from another* (Daniel 7:3), and then *a fourth beast, dreadful and terrible, and strong exceedingly; and it had great iron teeth: it devoured and brake in pieces... and it had ten horns* (Daniel 7:7). Daniel''s witness shows how the visions picture kingdoms as beasts with horns; it does not make the scarlet beast one of his. Daniel''s beasts rose *from the sea;* this one rises from the pit. And the waters where the whore sits are *peoples, and multitudes, and nations, and tongues* (17:15) — the nations she rides on the back of the beast out of the pit. The woman does not stand on her own strength; she sits upon the beast, the seducing city carried by the devouring power of the world, until the very horns she rode turn against her.'
 WHERE slug='revelation-17-the-woman-on-the-scarlet-beast-seven-heads-and-ten-horns-daniel-7';

UPDATE cross_reference_threads SET title = E'The ten horns make war with the Lamb, and the Lamb shall overcome them — Lord of lords and King of kings (Deuteronomy 10, Daniel 2)', summary_md = E'*The ten horns which thou sawest are ten kings, which have received no kingdom as yet; but receive power as kings one hour with the beast* (Revelation 17:12); *These have one mind, and shall give their power and strength unto the beast. These shall make war with the Lamb, and the Lamb shall overcome them: for he is Lord of lords, and King of kings: and they that are with him are called, and chosen, and faithful* (17:13-14). Daniel was shown the like and stands as a witness: *the ten horns out of this kingdom are ten kings that shall arise* (Daniel 7:24). But the angel interprets Revelation''s horns in Revelation''s own words — kings given one hour, lending their strength to the beast that ascends out of the pit (17:8). But against them stands the Lamb, and the title he bears is the divine name from the Torah itself: *For Yahuah Elohaychem (the LORD your God) is Elohim (God) of gods, and Lord of lords, a great Elohim (God), a mighty, and a terrible* (Deuteronomy 10:17). The slain Lamb who overcomes the kings is *Lord of lords* — the Formed who wears the very title the LORD bears in Moses'' charge to Yashar''el (Israel). Even Babylon''s king confessed it: *your Elohim (God) is a Elohim (God) of gods, and a Yahuah (Lord) of kings* (Daniel 2:47); and the great Hallel sang it, *O give thanks to the Lord of lords: for his mercy endureth for ever* (Psalm 136:3). The same name is written on the rider''s vesture — *KING OF KINGS, AND LORD OF LORDS* (Revelation 19:16) — and Paul names him *the blessed and only Potentate, the King of kings, and Lord of lords* (1 Timothy 6:15). The ten kings hold power one hour; the Lamb holds it for ever. They make war and are overcome, for he is the one only Sovereign above every throne, and they that are with him are *called, and chosen, and faithful.*'
 WHERE slug='revelation-17-the-lamb-shall-overcome-them-lord-of-lords-and-king-of-kings-deuteronomy-10-daniel-2';

UPDATE cross_reference_threads SET title = E'The ten horns shall hate the whore and burn her with fire — the lovers turned against the harlot (Ezekiel 16 and 23)', summary_md = E'*And the ten horns which thou sawest upon the beast, these shall hate the whore, and shall make her desolate and naked, and shall eat her flesh, and burn her with fire* (Revelation 17:16); *For Elohim (God) hath put in their hearts to fulfil his will* (17:17). The harlot''s own paramours become her executioners — and this exact turn is the prophets'' sentence on the unfaithful city. Ezekiel spoke it twice. *Behold, therefore I will gather all thy lovers, with whom thou hast taken pleasure... I will even gather them round about against thee, and will discover thy nakedness unto them* (Ezekiel 16:37) — the lovers gathered against her to strip her bare; *and they shall burn thine houses with fire, and execute judgments upon thee... and I will cause thee to cease from playing the harlot* (Ezekiel 16:41) — the fire that ends her harlotry. And of the second harlot-city: *they shall deal with thee hatefully, and shall take away all thy labour, and shall leave thee naked and bare* (Ezekiel 23:29), delivered into the hand of *them whom thou hatest.* The kings who fornicated with the whore turn and hate her, strip her, and burn her — exactly as the prophet foretold of the harlot-city, the lovers become haters. Against Babylon, Jeremiah summoned the instrument: *a people shall come from the north, and a great nation, and many kings shall be raised up from the coasts of the earth* (Jeremiah 50:41). And the restored library names the law of her end: *The reward of your whoredom shall be in your bosom, therefore shall you receive recompence* (2 Esdras 15:55); *And you shall be cast down by them as stubble, and they shall be to you as fire* (2 Esdras 15:61). The wages of her whoredom are paid back into her own bosom; the powers Yahuah (God) raises become fire to her, and *the woman which thou sawest is that great city, which reigneth over the kings of the earth* (Revelation 17:18) is consumed as stubble — the counterfeit city fallen, set forever against the holy city that is the true bride.'
 WHERE slug='revelation-17-the-ten-horns-shall-hate-the-whore-and-burn-her-with-fire-ezekiel-16-and-23';

UPDATE cross_reference_threads SET title = E'The marriage of the Lamb, the Bride arrayed in fine linen (Isaiah 61 and 54, Hosea 2)', summary_md = E'*Let us be glad and rejoice, and give honour to him: for the marriage of the Lamb is come, and his wife hath made herself ready. And to her was granted that she should be arrayed in fine linen, clean and white: for the fine linen is the righteousness of saints* (Revelation 19:7-8). This marriage is the covenant the prophets sang for centuries. Isaiah heard the Bride rejoice: *he hath covered me with the robe of righteousness, as a bridegroom decketh himself with ornaments, and as a bride adorneth herself with her jewels* (Isaiah 61:10) — the robe of righteousness is the very fine linen, *the righteousness of saints*, with which the wife of the Lamb is clothed; she does not weave it of herself, she is covered by the One who makes her ready. And the Bridegroom is no stranger: *thy Maker is thine husband; Yahuah Tseva''ot (LORD of hosts) is his name; and thy Redeemer the Holy One of Yashar''el (Israel)* (Isaiah 54:5). The Lamb who weds his Bride is her Maker and Redeemer, Yahuah (LORD) come in flesh, taking back the people he had for a small moment let go — *with great mercies will I gather thee* (Isaiah 54:7). She is the wife of Hosea''s betrothal, the one who had played the harlot, brought into the wilderness and wooed back there: *I will betroth thee unto me for ever; yea, I will betroth thee unto me in righteousness, and in judgment, and in lovingkindness, and in mercies* (Hosea 2:19), *I will even betroth thee unto me in faithfulness: and thou shalt know Yahuah (LORD)* (Hosea 2:20). The betrothal *in righteousness* is answered by the Bride arrayed in the *righteousness of saints*; the great whore is judged and the divorced house, brought into the wilderness, is betrothed again there — *I will say to them which were not my people, Thou art my people* (Hosea 2:23). The royal wedding-song shows her brought to the king: *the king''s daughter is all glorious within: her clothing is of wrought gold... she shall be brought unto the king in raiment of needlework* (Psalm 45:13-14). And then the word is sealed with a blessing: *Blessed are they which are called unto the marriage supper of the Lamb* (Revelation 19:9). The betrothal in the wilderness is the road of the homecoming the prophets promised, and the called are blessed.'
 WHERE slug='revelation-19-the-marriage-of-the-lamb-the-bride-in-fine-linen-isaiah-61-and-54-and-hosea-2';

UPDATE cross_reference_threads SET title = E'The sea beast and the false prophet cast into the lake of fire before the reign (Daniel 7)', summary_md = E'*And the beast was taken, and with him the false prophet that wrought miracles before him, with which he deceived them that had received the mark of the beast, and them that worshipped his image. These both were cast alive into a lake of fire burning with brimstone* (Revelation 19:20). The beast taken here is the beast out of the sea (Revelation 13:1), and the false prophet with him is the beast out of the earth (Revelation 13:11) — both cast alive into the lake before the reign begins. Daniel saw the like in his own vision: *I beheld then because of the voice of the great words which the horn spake: I beheld even till the beast was slain, and his body destroyed, and given to the burning flame* (Daniel 7:11). Daniel''s beast, whose little horn had *eyes like the eyes of man, and a mouth speaking great things* (Daniel 7:8), is slain and given to the burning flame — a witness to the same kind of end, not the key that decides who Revelation''s beasts are. The sea beast and the false prophet who deceived by miracles are cast into the lake of fire burning with brimstone, while *the remnant were slain with the sword of him that sat upon the horse, which sword proceeded out of his mouth* (Revelation 19:21). The word of the rider does what no horn''s great words could withstand; the proud mouths are silenced, and the two beasts are in the lake before the thousand years begin.'
 WHERE slug='revelation-19-the-beast-and-false-prophet-cast-into-the-lake-of-fire-daniel-7';

UPDATE cross_reference_threads SET title = E'The thrones of judgment and the first resurrection (Daniel 7, Ezekiel 37, Isaiah 26)', summary_md = E'*And I saw thrones, and they sat upon them, and judgment was given unto them... and they lived and reigned with Messiah (Christ) a thousand years... This is the first resurrection* (Revelation 20:4-5). Daniel saw the like: *I beheld till the thrones were cast down, and the Ancient of days did sit... his throne was like the fiery flame* (Daniel 7:9), and the verdict Daniel was shown is the verdict here — *judgment was given to the saints of the El Elyon (most High); and the time came that the saints possessed the kingdom* (Daniel 7:22). The ones who refused the mark of the beast out of the sea are the ones now on the thrones; as Daniel was shown the saints possessing the kingdom, so John sees them reign the thousand years — Daniel a witness, Revelation speaking for itself. And the raising of the slain is Ezekiel''s valley stood up alive: *the breath came into them, and they lived, and stood up upon their feet, an exceeding great army* (Ezekiel 37:10), for Yahuah (LORD) had sworn, *Behold, O my people, I will open your graves, and cause you to come up out of your graves* (Ezekiel 37:12). It is the hope Isaiah sang plainest: *Thy dead men shall live... Awake and sing, ye that dwell in dust... and the earth shall cast out the dead* (Isaiah 26:19). The Hebrew library names the great restoring that waits beyond the thousand years: *the earth shall restore those that are asleep in her... and the secret places shall deliver those souls that were committed to them* (2 Esdras 7:32) — the earth giving back all her sleepers for the judgment, against which the first resurrection stands out as the early exception, the righteous seed raised first to reign. And it comes in ranks, as Paul taught: *every man in his own order: Messiah (Christ) the firstfruits; afterward they that are Messiah''s (Christ''s) at his coming* (1 Corinthians 15:23) — the first resurrection of the slain who reign, and then *the rest of the dead* who *lived not again until the thousand years were finished* (Revelation 20:5). The thrones set, the graves opened, the dust awakened — the slain of the witness raised to reign.'
 WHERE slug='revelation-20-the-thrones-of-judgment-and-the-first-resurrection-daniel-7-ezekiel-37';

UPDATE cross_reference_threads SET title = E'The books were opened, and the book of life (Daniel 7 and 12, Malachi 3)', summary_md = E'*And I saw the dead, small and great, stand before Elohim (God); and the books were opened: and another book was opened, which is the book of life: and the dead were judged out of those things which were written in the books, according to their works* (Revelation 20:12). Daniel saw the like: *the judgment was set, and the books were opened* (Daniel 7:10). This is the one reckoning of the dead the seventh trumpet already sounded — *the time of the dead, that they should be judged* (Revelation 11:18) — shown here again in full. Daniel was told deliverance comes to *every one that shall be found written in the book* (Daniel 12:1), and that *many of them that sleep in the dust of the earth shall awake, some to everlasting life, and some to shame and everlasting contempt* (Daniel 12:2) — the very division that falls at the throne, some found written in the book of life and some cast into the lake of fire. The book of the living the psalmist knew can be written in or blotted out — *Let them be blotted out of the book of the living, and not be written with the righteous* (Psalm 69:28) — names written, never added, but able to be blotted out. Malachi names the same heavenly record kept for the faithful: *a book of remembrance was written before him for them that feared Yahuah (LORD), and that thought upon his name* (Malachi 3:16). And the works are recorded and repaid, as Isaiah heard: *Behold, it is written before me: I will not keep silence, but will recompense* (Isaiah 65:6). The Hebrew library shows the scene itself — *the Head of Days... seated Himself upon the throne of His glory, And the books of the living were opened before Him* (1 Enoch 47:3); *the Lord of the sheep opened the books of the living, and the books of the sinners were opened* (1 Enoch 90:12). And the book of life is named already in the Apocalypse: *the book of life of the Lamb slain from the foundation of the world* (Revelation 13:8) — the names written before the world was. The books of works and the book of life are opened together; *whosoever was not found written in the book of life was cast into the lake of fire* (Revelation 20:15).'
 WHERE slug='revelation-20-the-books-were-opened-and-the-book-of-life-daniel-7-and-12';

UPDATE cross_reference_threads SET title = E'No temple, no sun — Yahuah (LORD) and the Lamb the temple, the glory of Elohim (God) the light (Isaiah 60)', summary_md = E'In the new Jerusalem the dwelling-place and the light-bearer are one and the same — Elohim (God) himself. *And I saw no temple therein: for Yahuah Elohim (the Lord God) Almighty and the Lamb are the temple of it* (Revelation 21:22); *And the city had no need of the sun, neither of the moon, to shine in it: for the glory of Elohim (God) did lighten it, and the Lamb is the light thereof* (Revelation 21:23). This is Isaiah''s promise: *The sun shall be no more thy light by day; neither for brightness shall the moon give light unto thee: but Yahuah (LORD) shall be unto thee an everlasting light, and thy Elohim (God) thy glory* (Isaiah 60:19) — and here the One on the throne and the Lamb (the Father and the Formed Son) are together the temple and the light, the glory of Elohim (God) lightening the city and the Lamb its lamp. Then the nations walk in its light — the tribes, the company of nations promised to Jacob, *a nation and a company of nations shall be of thee* (Genesis 35:11) — as Isaiah saw: *the nations of them which are saved shall walk in the light of it: and the kings of the earth do bring their glory and honour into it* (Revelation 21:24), fulfilling *the Gentiles shall come to thy light, and kings to the brightness of thy rising* (Isaiah 60:3); and the gates stand open as Isaiah promised — *Therefore thy gates shall be open continually; they shall not be shut day nor night; that men may bring unto thee the forces of the Gentiles, and that their kings may be brought* (Isaiah 60:11) — for in the city *the gates of it shall not be shut at all by day: for there shall be no night there* (Revelation 21:25). The Hebrew library knew this hidden city would one day appear: *the bride shall appear, and she coming forth shall be seen, that now is withdrawn from the earth* (2 Esdras 7:26). She is shown at last — the holy Jerusalem revealed, lit by the glory of Elohim (God), her gates never shut, into which nothing unclean enters, *but they which are written in the Lamb''s book of life* (Revelation 21:27).'
 WHERE slug='revelation-21-no-temple-no-sun-the-glory-of-elohim-the-light-isaiah-60';

UPDATE cross_reference_threads SET title = E'They shall see his face, and his name in their foreheads (Exodus 33, Psalm 17, Numbers 6)', summary_md = E'*And they shall see his face; and his name shall be in their foreheads* (Revelation 22:4). What was denied to Moses is granted to the servants. To the one who sought the glory the word came: *Thou canst not see my face: for there shall no man see me, and live* (Exodus 33:20). That barrier is taken away in the restored city — the face no man could see and live is now seen by those who live for ever. David''s hope is fulfilled: *I will behold thy face in righteousness: I shall be satisfied, when I awake, with thy likeness* (Psalm 17:15) — the waking from the dust into the open sight of Elohim (God). And both halves of the priestly blessing stand complete: *Yahuah (LORD) make his face shine upon thee* (Numbers 6:25), and *they shall put my name upon the children of Yashar''el (Israel); and I will bless them* (Numbers 6:27). The shining face the priests invoked is now beheld; the name laid upon the people is now written on their foreheads. That name on the forehead is the seal already set in the seventh chapter — *till we have sealed the servants of our Elohim (God) in their foreheads* (Revelation 7:3) — the mark of the living Elohim (God) set on the servants before the winds of the Day were loosed, before the sifting, the counter-sign to the mark of the beast, now seen for what it always was: the name of the One they serve, worn before the face they see.'
 WHERE slug='revelation-22-they-shall-see-his-face-his-name-in-their-foreheads-exodus-33';

UPDATE cross_reference_thread_members m SET member_note = E'Daniel 12:4 — *seal the book, even to the time of the end* Daniel shown a sealed book, a witness that Yahuah (LORD) keeps his counsel shut until its hour; Revelation names the Lamb as the One who prevails to open this book (Revelation 5:4-5).'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
