UPDATE cross_reference_thread_members m SET member_note = E'Matthew 24:31 — *a great sound of a trumpet, and they shall gather together his elect from the four winds* the Olivet trumpet-gathering of the scattered at his return — a witness set beside, not the same event as, the catching-up after the reign: *caught up together with them in the clouds, to meet Yahuah (Lord) in the air* (1 Thessalonians 4:17).'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='1-thessalonians-4-the-dead-in-messiah-rise-the-trump-of-gathering-isaiah-27-daniel-12' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='1-thessalonians' AND sv.chapter_number=4 AND sv.verse_number=17
   AND tv.edition_slug='canon' AND tv.book_slug='matthew' AND tv.chapter_number=24 AND tv.verse_number=31
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';


