   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'The reign goes before the destination: Zechariah''s *every one that is left of all the nations which came against Yerushalayim (Jerusalem) shall even go up from year to year to worship the King, Yahuah (the LORD) Tseva''ot (of hosts), and to keep the feast of tabernacles* is the worship of the appointed reign, the nations left alive receiving priestly instruction from the gathered seed. The multitude before the throne is that same seed at the destination, after the reign, the little season and the judgment.'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
