   AND tv.edition_slug='canon' AND tv.book_slug='deuteronomy' AND tv.chapter_number=18 AND tv.verse_number=15
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'*The beast that ascendeth out of the bottomless pit shall make war against them, and shall overcome them, and kill them* has its like in Daniel''s *the same horn made war with the saints, and prevailed against them* — Daniel was shown the like. In Revelation it is the beast out of the pit, rising in the little season after the reign, that makes war on the two houses.'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='two-witnesses-and-the-two-olive-trees' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=11 AND sv.verse_number=7
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=21
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'*A time, and times, and half a time* has its like in Daniel''s little-horn vision; Daniel was shown a time, times and a half as well. Revelation''s own measure for the woman in the wilderness stands in its own place.'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='woman-clothed-with-the-sun-and-the-seed-war' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=12 AND sv.verse_number=14
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=25
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'The composite — leopard-bodied, bear-footed, lion-mouthed — gathers the marks of Daniel''s first three beasts (lion, bear, leopard) on the beast out of the sea — Daniel as witness to the imagery, not the key to the figure.'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='beast-from-the-sea-and-daniel-7' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=13 AND sv.verse_number=2
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=4
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'*A mouth speaking great things and blasphemies; and power was given unto him to continue forty and two months* has its like in Daniel — *he shall speak great words against the most High, and shall wear out the saints of the most High, and think to change times and laws: and they shall be given into his hand until a time and times and the dividing of time.* Daniel was shown the like; Revelation''s forty-two months keep their own measure.'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='beast-from-the-sea-and-daniel-7' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=13 AND sv.verse_number=5
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=25
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'The deadly head-wound healed picks up the little-horn''s *eyes like the eyes of man, and a mouth speaking great things* — Daniel was shown the like; in Revelation it is the beast out of the sea, Babel''s kingdom, bearing the composite marks.'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='beast-from-the-sea-and-daniel-7' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=13 AND sv.verse_number=3
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=8
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'The dominion *over all kindreds, and tongues, and nations* is the counterfeit of the dominion given to *one like the Son of Adam* in Daniel 7:14 — the beast out of the sea, Babel''s kingdom, imitates the Messianic kingship-grant, but its dominion is not everlasting; it is cast alive into the lake of fire before the reign (Revelation 19:20).'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='beast-from-the-sea-and-daniel-7' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=13 AND sv.verse_number=7
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=14
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'*One sat like unto the Son of Adam* is the same kaph-comparative as Daniel 7:13''s *one like the Son of Adam.* The kaph honors Yahusha''s (Jesus''s) incarnation; the harmonized identification is Yahusha himself — the figure thrusts his own sickle (v.16), the agency is the King''s, and the reaping is on the wicked, as Joel''s sickle is (Joel 3:13) — the kings the three unclean spirits gather to Armageddon (Revelation 16:13-16).'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='144000-on-mount-tsion-and-the-harvest' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=14 AND sv.verse_number=14
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=13
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'*Thrust in thy sickle, and reap: for the time is come for thee to reap; for the harvest of the earth is ripe* is verbatim Joel — *Put ye in the sickle, for the harvest is ripe: come, get you down; for the press is full, the fats overflow* — Joel''s sickle and winepress both fall on the wicked, *for their wickedness is great,* and the seer doubles them the same way.'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='144000-on-mount-tsion-and-the-harvest' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=14 AND sv.verse_number=15
   AND tv.edition_slug='canon' AND tv.book_slug='joel' AND tv.chapter_number=3 AND tv.verse_number=13
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'*The great river Euphrates; and the water thereof was dried up, that the way of the kings of the east might be prepared* picks up Isaiah''s gathering-prophecy — *Yahuah (the LORD)... with his mighty wind shall he shake his hand over the river, and shall smite it in the seven streams, and make men go over dryshod* — the Tanakh''s Euphrates-divided-for-the-gathering, fulfilled at the sixth bowl: the kings of the east are the gathered seed coming home through the dried river, as Isaiah goes on, *And there shall be an highway for the remnant of his people, which shall be left, from Assyria; like as it was to Yashar''el (Israel) in the day that he came up out of the land of Egypt* (Isaiah 11:16).'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='seven-bowls-and-the-exodus-plagues' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=16 AND sv.verse_number=12
   AND tv.edition_slug='canon' AND tv.book_slug='isaiah' AND tv.chapter_number=11 AND tv.verse_number=15
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'*The beast was taken, and with him the false prophet... These both were cast alive into a lake of fire* picks up Daniel — *I beheld even till the beast was slain, and his body destroyed, and given to the burning flame* — Daniel was shown the like; in Revelation it is the beast out of the sea and the beast out of the earth, the false prophet, cast alive into the lake before the reign.'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='marriage-supper-and-return-of-the-king' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=19 AND sv.verse_number=20
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=11
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'The thrones — *I saw thrones, and they sat upon them, and judgment was given unto them* — pick up Daniel 7''s enthronement-vision: *I beheld till the thrones were cast down (set in place), and the Ancient of days did sit* — Daniel saw thrones set as well; a witness beside the reign the seer is shown.'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='appointed-reign-on-the-earth-and-the-priestly-remnant' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=20 AND sv.verse_number=4
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=9
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'*We which are alive and remain... shall not prevent them which are asleep* — Paul''s word that the asleep are not passed over at his coming. The first resurrection the seer sees enacted raises them first, the worthy of the seed, into the priestly company of the reign.'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='appointed-reign-on-the-earth-and-the-priestly-remnant' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=20 AND sv.verse_number=4
   AND tv.edition_slug='canon' AND tv.book_slug='1-thessalonians' AND tv.chapter_number=4 AND tv.verse_number=15
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'*I saw a great white throne, and him that sat on it... and the books were opened* has its like in Daniel — *the Ancient of days did sit, whose garment was white as snow... thousand thousands ministered unto him, and ten thousand times ten thousand stood before him: the judgment was set, and the books were opened.* Daniel was shown the like; Revelation''s throne stands in its own vision.'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='great-white-throne-and-the-one-judgment-from-two-angles' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=20 AND sv.verse_number=11
   AND tv.edition_slug='canon' AND tv.book_slug='daniel' AND tv.chapter_number=7 AND tv.verse_number=9
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';

UPDATE cross_reference_thread_members m SET member_note = E'*The nations of them which are saved shall walk in the light of it: and the kings of the earth do bring their glory and honour into it* is verbatim Isaiah — *the nations shall come to thy light, and kings to the brightness of thy rising* — the nations of the closing panel are the tribes, the company of nations promised to Ya''aqov (Jacob) (Genesis 35:11), walking in the light of the city.'
  FROM cross_reference_threads t, cross_references x, _s434_lu sv, _s434_lu tv
 WHERE t.slug='new-heavens-new-earth-and-the-leaves-for-healing' AND m.thread_id=t.id AND m.cross_reference_id=x.id
   AND sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=21 AND sv.verse_number=24
   AND tv.edition_slug='canon' AND tv.book_slug='isaiah' AND tv.chapter_number=60 AND tv.verse_number=3
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual';


-- ===== new: Revelation 17:8-11, the beast out of the pit =====

WITH input(src_edition, src_slug, src_ch, src_v, tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  ('canon','revelation',17,8, 'canon','genesis',10,8, 'free', E'*And Cush begat Nimrod: he began to be a mighty one in the earth.* (Genesis 10:8). The angel tells the seer that *The beast that thou sawest was, and is not; and shall ascend out of the bottomless pit, and go into perdition* (Revelation 17:8) — and the library names the man whose kingdom this beast carries. Nimrod *began to be a mighty one in the earth;* he was a king of flesh who rose, ruled, and died. That is the *was.* He is not among the living now; that is the *is not.* Yet he is not the one cast down from heaven. He is the one the dragon raises, the mighty one of the earth who rules from the underworld, and so the beast *yet is* (Revelation 17:8), waiting below for the hour he is let up.'),
  ('canon','revelation',17,8, 'canon','genesis',10,10, 'free', E'*And the beginning of his kingdom was Babel, and Erech, and Accad, and Calneh, in the land of Shinar.* (Genesis 10:10). Here is where the beast''s kingdom began: *the beginning of his kingdom was Babel.* Babel, Babylon, Baal: one name for one rebellion, and Nimrod is its king. The woman on the scarlet beast bears *BABYLON THE GREAT* on her forehead (Revelation 17:5), and the beast that carries her is the king of the first Babel, *the beast that was, and is not, and yet is* (Revelation 17:8). The city and the king belong together from Shinar to the end; what began at Babel is what rides out of the pit.'),
  ('canon','revelation',17,8, 'canon','revelation',9,11, 'free', E'*And they had a king over them, which is the angel of the bottomless pit, whose name in the Hebrew tongue is Abaddon, but in the Greek tongue hath his name Apollyon.* (Revelation 9:11). The pit has a king, and the book has already named him: *the angel of the bottomless pit,* Abaddon, Apollyon, the Destroyer. He is the same one who *shall ascend out of the bottomless pit* (Revelation 17:8): Babel''s king, Nimrod, raised up by the dragon and ruling from below. Revelation names him twice, once as the king over the locusts of the pit and once as the beast that was, and is not, and yet is.'),
  ('canon','revelation',17,8, 'canon','revelation',11,7, 'free', E'*And when they shall have finished their testimony, the beast that ascendeth out of the bottomless pit shall make war against them, and shall overcome them, and kill them.* (Revelation 11:7). The beast of 17:8 has already been seen at work. When the two witnesses, the two houses Yahudah (Judah) and Yashar''el (Israel), have finished their testimony through the reign, *the beast that ascendeth out of the bottomless pit* makes war on them and kills them. It is the same beast: the one who *shall ascend out of the bottomless pit* (Revelation 17:8). He rises after the reign, in the little season, not before it.'),
  ('canon','revelation',17,8, 'canon','revelation',20,7, 'free', E'*And when the thousand years are expired, Satan shall be loosed out of his prison,* (Revelation 20:7). The beast *shall ascend out of the bottomless pit* (Revelation 17:8), but not of himself. Through the reign the pit is shut and sealed. When the thousand years are expired the dragon is loosed out of his prison, and the one he raises comes up with him. The beast that was, and is not, and yet is, ascends in the little season, when the dragon goes out *to deceive the nations which are in the four quarters of the earth* (Revelation 20:8). Then the beast goes into perdition (Revelation 17:8).'),
  ('canon','revelation',17,11, 'canon','revelation',13,1, 'free', E'*And I stood upon the sand of the sea, and saw a beast rise up out of the sea, having seven heads and ten horns, and upon his horns ten crowns, and upon his heads the name of blasphemy.* (Revelation 13:1). The beast out of the sea had seven heads; the beast out of the pit *is the eighth, and is of the seven* (Revelation 17:11). He is of the seven because the same spirit of Babel ran through every head. He is the eighth because he is not one of them: another beast, coming from another place. The beast out of the sea rose from the sea, and he and the false prophet are cast alive into the lake before the reign (Revelation 19:20). The beast out of the pit rises from below after the reign. The two are kin, but they are never the same beast.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _s434_lu sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _s434_lu tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'revelation-17-the-beast-that-was-and-is-not-and-yet-is-the-pit-beast-of-the-little-season',
       E'The beast that was, and is not, and yet is — the beast out of the pit, Babel''s king (Genesis 10, Revelation 9, 11, 13, 20)',
       E'*The beast that thou sawest was, and is not; and shall ascend out of the bottomless pit, and go into perdition: and they that dwell on the earth shall wonder, whose names were not written in the book of life from the foundation of the world, when they behold the beast that was, and is not, and yet is* (Revelation 17:8). *And the beast that was, and is not, even he is the eighth, and is of the seven, and goeth into perdition* (Revelation 17:11). The angel names the beast by where it comes from: it *shall ascend out of the bottomless pit.* That is the beast out of the pit, not the beast out of the sea. The library names the king whose kingdom it carries: *And Cush begat Nimrod: he began to be a mighty one in the earth* (Genesis 10:8); *And the beginning of his kingdom was Babel, and Erech, and Accad, and Calneh, in the land of Shinar* (Genesis 10:10). Babel, Babylon, Baal: one rebellion and one king. He *was* a king in the earth. He *is not* among the living. Yet he *is,* because he is not the one cast down from heaven but the one the dragon raises, ruling from the underworld. The book has already shown his throne: *they had a king over them, which is the angel of the bottomless pit, whose name in the Hebrew tongue is Abaddon, but in the Greek tongue hath his name Apollyon* (Revelation 9:11). Through the reign he is sealed in the pit. Then *when the thousand years are expired, Satan shall be loosed out of his prison* (Revelation 20:7), and the one the dragon raises comes up with him. The book has shown what he does then: *the beast that ascendeth out of the bottomless pit shall make war against them, and shall overcome them, and kill them* (Revelation 11:7). He makes war on the two witnesses, the two houses, after their testimony in the reign is finished. He is *the eighth, and is of the seven.* He is of the seven because the beast out of the sea, which *rise up out of the sea, having seven heads and ten horns* (Revelation 13:1), carried his same Babel spirit. He is the eighth because he is another beast. The beast out of the sea and the false prophet are already in the lake before the reign. The beast out of the pit rises after it, in the little season, and *goeth into perdition.*',
       sv.verse_id, ev.verse_id, 'free', 9425
  FROM _s434_lu sv, _s434_lu ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='revelation' AND sv.chapter_number=17 AND sv.verse_number=8
   AND ev.edition_slug='canon' AND ev.book_slug='revelation' AND ev.chapter_number=17 AND ev.verse_number=11
ON CONFLICT (slug) DO NOTHING;

